//=============================================================================
// HPVersusGame.
//
// Free-for-all arena mode for 2 to 8 participants.
//
// Dedicated server (preferred first test, removes the listen-host Harry0 case):
//   UCC.exe server Arena.unr?game=HGame.HPVersusGame?MaxPlayers=2 -log=Server.log
// Listen host:
//   open Arena.unr?game=HGame.HPVersusGame?listen?MaxPlayers=2
// Join:
//   open <host-ip>
//
// The map must contain one HPVersusStart for every configured slot.
//=============================================================================

class HPVersusGame extends GameInfo;

var int ScoreLimit;
var float RespawnDelay;
var bool bMatchInProgress;
var name VersusPhase;
var float PhaseEndTime;
var float CountdownDuration;
var float MatchOverDuration;
var byte PendingLoginSlot;       // slot being used by the Login currently inside Super.Login()
var bool bHasPendingLoginSlot;
var HPVersusHealthPickup VersusHealthPickupA;
var HPVersusHealthPickup VersusHealthPickupB;
var HPVersusSpeedPickup VersusSpeedPickup;
var bool bVersusMechanicsProbe;
var bool bVersusMechanicsProbeComplete;
var byte VersusMechanicsProbeStage;
var float VersusMechanicsProbeNextTime;
var HPVersusSpongifyPad VersusProbeSpongifyPad;
var HPVersusSpongifyTarget VersusProbeSpongifyTarget;
var HPVersusInteractionArena VersusInteractionArena;
var bool bVersusCharacterAuditComplete;
var string VersusProbeCharacterA;
var string VersusProbeCharacterB;

function InitGame(string Options, out string Error)
{
    local string InOpt;

    Super.InitGame(Options, Error);
    if (MaxPlayers < 2)
        MaxPlayers = 2;
    if (MaxPlayers > 8)
        MaxPlayers = 8;

    InOpt = ParseOption(Options, "ScoreLimit");
    if (InOpt != "")
        ScoreLimit = int(InOpt);
    if (ScoreLimit < 1)
        ScoreLimit = 3;

    bVersusMechanicsProbe = ParseOption(Options, "VersusMechanicsProbe") ~= "1";

    Log("=== HPVersusGame loaded. ScoreLimit=" $ ScoreLimit
        $ " MechanicsProbe=" $ string(bVersusMechanicsProbe) $ " ===");
}

event PostBeginPlay()
{
    Super.PostBeginPlay();
    bMatchInProgress = False;
    VersusPhase = 'WaitingForPlayers';
    SetTimer(0.20, True);
    CleanupLegacyHarryActors();
    SpawnVersusDirector();
    SpawnVersusPickups();
    SpawnVersusInteractionArena();
    UpdateVersusGRI();
}

function bool IsVersusInteractionMap()
{
    return InStr(Caps(string(Level)), "HPV_INTERACTIONS") >= 0;
}

function SpawnVersusInteractionArena()
{
    if (Role != ROLE_Authority || !IsVersusInteractionMap())
        return;
    if (VersusInteractionArena == None)
        VersusInteractionArena = Spawn(
            Class'HPVersusInteractionArena',,,
            GetVersusPickupCenter(), rot(0,0,0));
    Log("HPVersusInteractionArena spawn actor="
        $ string(VersusInteractionArena)
        $ " level=" $ string(Level));
}

function Vector GetVersusPickupCenter()
{
    local HPVersusStart S;
    local Vector Center;
    local int Count;

    foreach AllActors(Class'HPVersusStart', S)
    {
        if (!S.bEnabled)
            continue;
        Center += S.Location;
        Count++;
    }
    if (Count > 0)
        Center = Center / float(Count);
    return Center;
}

function SpawnVersusPickups()
{
    local Vector Center;
    local Vector Offset;

    if (Role != ROLE_Authority)
        return;
    Center = GetVersusPickupCenter();

    Offset.X = -120.0;
    if (VersusHealthPickupA == None)
        VersusHealthPickupA = Spawn(
            Class'HPVersusHealthPickup',,, Center + Offset, rot(0,0,0));
    Offset.X = 120.0;
    if (VersusHealthPickupB == None)
        VersusHealthPickupB = Spawn(
            Class'HPVersusHealthPickup',,, Center + Offset, rot(0,0,0));
    Offset.X = 0.0;
    Offset.Y = 150.0;
    if (VersusSpeedPickup == None)
        VersusSpeedPickup = Spawn(
            Class'HPVersusSpeedPickup',,, Center + Offset, rot(0,0,0));

    Log("HPVersusPickups spawned healthA=" $ string(VersusHealthPickupA)
        $ " healthB=" $ string(VersusHealthPickupB)
        $ " speed=" $ string(VersusSpeedPickup)
        $ " center=" $ string(Center));
}

function ResetVersusPickups()
{
    if (VersusHealthPickupA == None
        || VersusHealthPickupB == None
        || VersusSpeedPickup == None)
        SpawnVersusPickups();
    if (VersusHealthPickupA != None)
        VersusHealthPickupA.ResetVersusPickup();
    if (VersusHealthPickupB != None)
        VersusHealthPickupB.ResetVersusPickup();
    if (VersusSpeedPickup != None)
        VersusSpeedPickup.ResetVersusPickup();
}

function bool GetVersusProbePlayers(out HPVersusHarry A, out HPVersusHarry B)
{
    local Pawn P;
    local HPVersusHarry H;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None || H.Player == None)
            continue;
        if (A == None)
            A = H;
        else if (H != A)
        {
            B = H;
            return True;
        }
    }
    return False;
}

function VersusProbeResult(bool bPassed, string CheckName)
{
    if (bPassed)
        Log("HPVersusMechanicsProbe PASS check=" $ CheckName);
    else
        Log("HPVersusMechanicsProbe FAIL check=" $ CheckName);
}

function RunVersusMechanicsProbe()
{
    local HPVersusHarry A;
    local HPVersusHarry B;
    local HPVersusFlipendo Flipendo;
    local HPVersusSpongify Spongify;
    local Vector ProbeLocation;
    local float RemainingCooldown;
    local HPVersusPRI ProbeAPRI;
    local HPVersusPRI ProbeBPRI;

    if (!bVersusMechanicsProbe || bVersusMechanicsProbeComplete
        || VersusPhase != 'InProgress'
        || Level.TimeSeconds < VersusMechanicsProbeNextTime
        || !GetVersusProbePlayers(A, B))
        return;

    if (VersusMechanicsProbeStage == 0)
    {
        Log("HPVersusMechanicsProbe START A=" $ string(A) $ " B=" $ string(B));
        ProbeAPRI = HPVersusPRI(A.PlayerReplicationInfo);
        ProbeBPRI = HPVersusPRI(B.PlayerReplicationInfo);
        if (ProbeAPRI != None)
            VersusProbeCharacterA = ProbeAPRI.SelectedCharacter;
        if (ProbeBPRI != None)
            VersusProbeCharacterB = ProbeBPRI.SelectedCharacter;
        A.ServerSelectVersusSpell(1);
        B.ServerSelectVersusSpell(3);
        VersusProbeResult(
            A.GetVersusSpellClass(A.SelectedVersusSpell) == Class'HPVersusMimblewimble'
            && B.GetVersusSpellClass(B.SelectedVersusSpell) == Class'HPVersusFlipendo'
            && A.GetVersusSpellClass(4) == Class'HPVersusAlohomora'
            && A.GetVersusSpellClass(5) == Class'HPVersusSpongify',
            "server-whitelist-selection");

        A.NextVersusServerCastTime = 0.0;
        A.ServerRequestCast(1.0, A.Rotation, A.GetVersusFallbackMuzzle(A.Rotation));
        RemainingCooldown = A.NextVersusServerCastTime - Level.TimeSeconds;
        VersusProbeResult(RemainingCooldown > 0.60 && RemainingCooldown < 0.80,
            "per-spell-server-cooldown");

        B.Health = 50;
        B.SetHealth(50);
        B.ClientSyncHealth(50);
        VersusHealthPickupA.RespawnTime = 0.50;
        VersusHealthPickupA.ResetVersusPickup();
        VersusHealthPickupA.TryPickup(B);
        VersusProbeResult(B.Health == 75 && !VersusHealthPickupA.bAvailable,
            "health-pickup-clamp-and-consume");

        VersusSpeedPickup.BoostDuration = 0.50;
        VersusSpeedPickup.ResetVersusPickup();
        VersusSpeedPickup.TryPickup(A);
        VersusProbeResult(A.IsVersusSpeedBoosted()
            && A.VersusSpeedMultiplier > 1.49,
            "speed-pickup-authority");

        B.HandleSpellDuelMimblewimble(None, B.Location);
        VersusProbeResult(B.Health == 67 && B.IsVersusSpellLocked(),
            "mimblewimble-damage-and-mute");
        B.HandleSpellDuelExpelliarmus(None, B.Location);
        VersusProbeResult(B.Health == 67 && B.VersusDisarmEndTime > Level.TimeSeconds,
            "expelliarmus-disarm-without-damage");

        ProbeLocation = B.Location;
        ProbeLocation.Z += 100.0;
        Flipendo = Spawn(Class'HPVersusFlipendo', A,, ProbeLocation, B.Rotation);
        if (Flipendo != None)
        {
            Flipendo.Instigator = A;
            Flipendo.SpellCharge = 1.0;
            Flipendo.Velocity = Normal(B.Location - A.Location) * Flipendo.Speed;
            Flipendo.OnSpellHitHarry(B, B.Location);
            Flipendo.Destroy();
        }
        VersusProbeResult(Flipendo != None && B.Health == 59
            && B.Physics == PHYS_Falling, "flipendo-damage-and-impulse");

        ProbeLocation = A.Location;
        ProbeLocation.Z += 8.0;
        VersusProbeSpongifyPad = Spawn(
            Class'HPVersusSpongifyPad',,, ProbeLocation, rot(0,0,0));
        ProbeLocation = A.Location;
        ProbeLocation.X += 180.0;
        ProbeLocation.Z += 80.0;
        VersusProbeSpongifyTarget = Spawn(
            Class'HPVersusSpongifyTarget',,, ProbeLocation, rot(0,0,0));
        if (VersusProbeSpongifyPad != None
            && VersusProbeSpongifyTarget != None)
        {
            VersusProbeSpongifyPad.Target = VersusProbeSpongifyTarget;
            VersusProbeSpongifyPad.fTimeToHitTarget = 2.0;
            Spongify = Spawn(Class'HPVersusSpongify', A,,
                VersusProbeSpongifyPad.Location, A.Rotation);
            if (Spongify != None)
            {
                Spongify.Instigator = A;
                Spongify.SpellCharge = 1.0;
                Spongify.OnSpellHitHPawn(
                    VersusProbeSpongifyPad,
                    VersusProbeSpongifyPad.Location);
                Spongify.Destroy();
            }
            VersusProbeSpongifyPad.OnBounce(A);
        }
        VersusProbeResult(Spongify != None
            && VersusProbeSpongifyPad != None
            && VersusProbeSpongifyPad.IsEnabled()
            && A.bVersusSpongifyActive
            && A.Physics == PHYS_Falling
            && VSize(A.Velocity) > 1.0,
            "spongify-authoritative-activation-and-bounce");

        VersusMechanicsProbeStage = 1;
        VersusMechanicsProbeNextTime = Level.TimeSeconds + 1.0;
        return;
    }

    if (VersusMechanicsProbeStage == 1)
    {
        VersusProbeResult(VersusHealthPickupA.bAvailable,
            "health-pickup-respawn-timer");
        VersusProbeResult(!A.IsVersusSpeedBoosted()
            && A.VersusSpeedMultiplier <= 1.01,
            "speed-expiry-reset");
        A.ApplyVersusSpeedBoost(1.5, 10.0);
        A.VersusKilledBy(B, 'MechanicsProbe');
        VersusProbeResult(A.bVersusDead && !A.IsVersusSpeedBoosted(),
            "death-clears-speed");
        VersusProbeResult(!A.bVersusSpongifyActive,
            "death-clears-spongify");
        VersusMechanicsProbeStage = 2;
        VersusMechanicsProbeNextTime = Level.TimeSeconds + RespawnDelay + 0.5;
        return;
    }

    VersusProbeResult(!A.bVersusDead && A.Health == 100
        && !A.IsVersusSpeedBoosted(), "respawn-restores-clean-state");
    ProbeAPRI = HPVersusPRI(A.PlayerReplicationInfo);
    ProbeBPRI = HPVersusPRI(B.PlayerReplicationInfo);
    VersusProbeResult(ProbeAPRI != None && ProbeBPRI != None
        && ProbeAPRI.SelectedCharacter ~= VersusProbeCharacterA
        && ProbeBPRI.SelectedCharacter ~= VersusProbeCharacterB
        && A.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterA)
        && B.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterB),
        "character-profile-survives-respawn");
    B.ApplyVersusSpeedBoost(1.5, 10.0);
    BeginVersusMatch();
    VersusProbeResult(!B.IsVersusSpeedBoosted() && B.Health == 100,
        "new-match-clears-speed");
    VersusProbeResult(ProbeAPRI.SelectedCharacter ~= VersusProbeCharacterA
        && ProbeBPRI.SelectedCharacter ~= VersusProbeCharacterB
        && A.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterA)
        && B.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterB),
        "character-profile-survives-new-match");
    if (VersusProbeSpongifyPad != None)
        VersusProbeSpongifyPad.Destroy();
    if (VersusProbeSpongifyTarget != None)
        VersusProbeSpongifyTarget.Destroy();
    bVersusMechanicsProbeComplete = True;
    Log("HPVersusMechanicsProbe COMPLETE");
}


function CleanupLegacyHarryActors()
{
    local harry H;

    foreach AllActors(Class'harry', H)
    {
        if (H == None)
            continue;

        if (HPVersusHarry(H) != None)
            continue;

        Log("HPVersusGame: destroying legacy single-player harry " $ string(H));
        H.Destroy();
    }
}

function SpawnVersusDirector()
{
    local Director D;

    foreach AllActors(Class'Director', D)
    {
        D.Destroy();
    }

    Spawn(Class'HPVersusDirector');
}

event PostLogin(PlayerPawn NewPlayer)
{
    local HPVersusHarry H;
    local harry LegacyHarry;
    local HPVersusPRI VPRI;

    Super.PostLogin(NewPlayer);

    H = HPVersusHarry(NewPlayer);
    if (H == None)
    {
        LegacyHarry = harry(NewPlayer);
        if (LegacyHarry != None)
        {
            Log("HPVersusGame: legacy host pawn logged in, enabling control: " $ string(NewPlayer));
            SetupLegacyHostPlayer(LegacyHarry);
        }
        else
        {
            Log("HPVersusGame: non-versus pawn logged in: " $ string(NewPlayer));
        }
        return;
    }

    VPRI = HPVersusPRI(NewPlayer.PlayerReplicationInfo);
    if (VPRI == None)
    {
        Log("HPVersusGame: expected HPVersusPRI for " $ string(NewPlayer));
        return;
    }
    VPRI.SetSelectedCharacter(VPRI.SelectedCharacter);
    H.ApplyCharacterSkin(VPRI.SelectedCharacter);
    H.SetupVersusPlayer();

    // Login assigns VersusSlot before Super.Login() so FindPlayerStart can pick
    // the correct HPVersusStart. Keep this fallback for old/listen edge cases.
    if (H.VersusSlot >= MaxPlayers)
        Log("HPVersusGame: invalid assigned slot=" $ H.VersusSlot);

    UpdateVersusGRI();

    Log("HPVersusGame: PostLogin player=" $ string(NewPlayer)
        $ " slot=" $ string(H.VersusSlot)
        $ " playerObj=" $ string(NewPlayer.Player)
        $ " loc=" $ string(NewPlayer.Location));

    BroadcastMessage(NewPlayer.PlayerReplicationInfo.PlayerName $ " joined Versus slot " $ H.VersusSlot $ " as " $ VPRI.SelectedCharacter);
}

function bool IsLocalViewportPlayer(PlayerPawn P)
{
    return P != None && P.Player != None && Viewport(P.Player) != None;
}

function SetupLegacyHostPlayer(harry H)
{
    if (H == None)
        return;

    H.bKeepStationary = False;
    H.bIsCaptured = False;
    H.bAllowHarryToDie = True;
    H.bCanMoveInSpecialPause = True;

    if (IsLocalViewportPlayer(H))
    {
        H.EnablePlayerInput();

        if (H.myHUD != None)
            H.myHUD.EndCutScene();

        if (H.Cam != None)
        {
            H.Cam.SetCameraMode(3);
            H.Cam.GotoState('StateStandardCam');
            H.Cam.InitTarget(H);
            H.Cam.InitPositionAndRotation(True);
        }
    }

    if (!H.IsInState('PlayerWalking'))
        H.GotoState('PlayerWalking');

    H.SetPhysics(PHYS_Walking);
    H.Health = 100;
}

//-----------------------------------------------------------------------------
// GRI wiring. Base GameInfo has no SetGRI(); it spawns GameReplicationInfoClass
// in PreBeginPlay and then calls InitGameReplicationInfo(). We override the
// latter to seed versus state on the spawned HPVersusGRI.
//-----------------------------------------------------------------------------

function InitGameReplicationInfo()
{
    Super.InitGameReplicationInfo();

    if (GameReplicationInfo != None && GameReplicationInfo.IsA('HPVersusGRI'))
    {
        HPVersusGRI(GameReplicationInfo).ScoreLimit = ScoreLimit;
        HPVersusGRI(GameReplicationInfo).MatchState = 'WaitingForPlayers';
        HPVersusGRI(GameReplicationInfo).bIsWarmup = True;
        HPVersusGRI(GameReplicationInfo).bIsRoundActive = False;
        HPVersusGRI(GameReplicationInfo).bMatchOver = False;
    }
}

function UpdateVersusGRI()
{
    local HPVersusGRI G;

    if (GameReplicationInfo == None)
        return;

    G = HPVersusGRI(GameReplicationInfo);
    if (G == None)
        return;

    G.ScoreLimit = ScoreLimit;
    G.bIsWarmup = VersusPhase == 'WaitingForPlayers' || VersusPhase == 'Countdown';
    G.bIsRoundActive = VersusPhase == 'InProgress';
    G.bMatchOver = VersusPhase == 'MatchOver';
    G.MatchState = VersusPhase;
    if (PhaseEndTime > Level.TimeSeconds)
        G.RoundTimer = int(PhaseEndTime - Level.TimeSeconds + 0.99);
    else
        G.RoundTimer = 0;
}

//-----------------------------------------------------------------------------
// Spawn selection. Base GameInfo.FindPlayerStart returns the FIRST
// bSinglePlayerStart for every joiner, which stacks both duelists on the map's
// vanilla Harry0 start. Pick an HPVersusStart by slot instead.
//-----------------------------------------------------------------------------

function NavigationPoint FindPlayerStart(Pawn Player, optional byte InTeam, optional string incomingName)
{
    local HPVersusStart S, Best;
    local HPVersusHarry Other;
    local byte Slot;
    local float Distance, Nearest, BestNearest;
    local bool bClear;

    if (HPVersusHarry(Player) != None)
        Slot = HPVersusHarry(Player).VersusSlot;
    else if (bHasPendingLoginSlot)
        Slot = PendingLoginSlot;

    foreach AllActors(Class'HPVersusStart', S)
    {
        if (!S.bEnabled || S.VersusSpawnIndex >= MaxPlayers)
            continue;

        bClear = True;
        Nearest = 1000000.0;
        foreach AllActors(Class'HPVersusHarry', Other)
        {
            if (Other == Player || !Other.bVersusRegistered || Other.bVersusDead)
                continue;
            Distance = VSize(Other.Location - S.Location);
            if (Distance < 96.0)
            {
                bClear = False;
                break;
            }
            if (Distance < Nearest)
                Nearest = Distance;
        }
        if (!bClear)
            continue;
        if (S.VersusSpawnIndex == Slot)
        {
            Best = S;
            break;
        }
        if (Best == None || Nearest > BestNearest)
        {
            Best = S;
            BestNearest = Nearest;
        }
    }

    if (Best != None)
    {
        Log("HPVersusGame: FindPlayerStart slot=" $ string(Slot) $ " start=" $ string(Best));
        return Best;
    }

    // RestartPlayer retries later if all starts are occupied. Never place an
    // arena pawn on the map's shared single-player start.
    return None;
}

function bool VersusStartIndexExists(byte Slot)
{
    local HPVersusStart S;
    foreach AllActors(Class'HPVersusStart', S)
        if (S.bEnabled && S.VersusSpawnIndex == Slot)
            return True;
    return False;
}

function Logout(Pawn Exiting)
{
    if (HPVersusHarry(Exiting) != None)
        HPVersusHarry(Exiting).bVersusRegistered = False;
    BroadcastMessage(string(Exiting) $ " left Versus");
    Super.Logout(Exiting);
}

function bool TooManyPlayers()
{
    local Pawn P;
    local HPVersusHarry H;
    local int Count;

    Count = 0;
    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H != None && H.bVersusRegistered)
            Count++;
    }

    Log("HPVersusGame: connected player count=" $ Count $ " MaxPlayers=" $ MaxPlayers);
    return Count >= MaxPlayers || NumPlayers >= MaxPlayers;
}

function byte ChooseVersusSlot()
{
    local Pawn P;
    local HPVersusHarry H;
    local int Slot;
    local bool bUsed;

    for (Slot = 0; Slot < MaxPlayers; Slot++)
    {
        bUsed = False;
        for (P = Level.PawnList; P != None; P = P.NextPawn)
        {
            H = HPVersusHarry(P);
            if (H != None && H.bVersusRegistered && H.VersusSlot == Slot)
            {
                bUsed = True;
                break;
            }
        }
        if (!bUsed && VersusStartIndexExists(byte(Slot)))
            return byte(Slot);
    }
    return 255;
}

event PlayerPawn Login
(
    string Portal,
    string Options,
    out string Error,
    class<playerpawn> SpawnClass
)
{
    local PlayerPawn NewPlayer;
    local HPVersusHarry H;
    local HPVersusPRI VPRI;
    local byte LoginSlot;
    local string LoginCharacter;

    if (TooManyPlayers())
    {
        Error = "Versus server is full.";
        return None;
    }

    // Clients still send their single-player class in the URL
    // (usually Class=HGame.harry). Force the arena pawn so each
    // connection gets its own controllable versus player.
    SpawnClass = Class'HPVersusHarry';
    LoginSlot = ChooseVersusSlot();
    if (LoginSlot == 255)
    {
        Error = "No free Versus start for this server capacity.";
        return None;
    }
    PendingLoginSlot = LoginSlot;
    bHasPendingLoginSlot = True;

    Log("HPVersusGame: Login forcing SpawnClass=HPVersusHarry slot=" $ string(LoginSlot)
        $ " portal=" $ Portal $ " options=" $ Options);

    NewPlayer = Super.Login(Portal, Options, Error, SpawnClass);

    bHasPendingLoginSlot = False;

    H = HPVersusHarry(NewPlayer);
    if (H != None)
    {
        LoginCharacter = "Harry";
        VPRI = HPVersusPRI(H.PlayerReplicationInfo);
        if (VPRI != None)
        {
            VPRI.SetSelectedCharacter(ParseOption(Options, "MPCharacter"));
            H.ApplyCharacterSkin(VPRI.SelectedCharacter);
            LoginCharacter = VPRI.SelectedCharacter;
        }
        H.VersusSlot = LoginSlot;
        H.bVersusRegistered = True;
        H.ClientSetVersusSlot(LoginSlot);
        Log("HPVersusGame: Login assigned player=" $ string(H)
            $ " slot=" $ string(H.VersusSlot)
            $ " character=" $ LoginCharacter
            $ " playerObj=" $ string(H.Player)
            $ " loc=" $ string(H.Location));
    }

    return NewPlayer;
}

function NotifyVersusDeath(HPVersusHarry Victim, Pawn Killer, name DamageType)
{
    local PlayerPawn KillerPlayer;
    local HPVersusPRI KillerPRI;

    if (Victim == None)
        return;
    if (!bMatchInProgress)
        return;

    Victim.VersusRespawnAt = Level.TimeSeconds + RespawnDelay;
    Victim.VersusRespawnSeconds = byte(int(RespawnDelay + 0.99));
    if (Victim.PlayerReplicationInfo != None)
        Victim.PlayerReplicationInfo.Deaths += 1;

    KillerPlayer = PlayerPawn(Killer);
    if (KillerPlayer != None && KillerPlayer != Victim)
    {
        KillerPRI = HPVersusPRI(KillerPlayer.PlayerReplicationInfo);
        if (KillerPRI != None)
        {
            KillerPRI.RoundScore++;
            BroadcastMessage(KillerPlayer.PlayerReplicationInfo.PlayerName $ " scores! " $ KillerPRI.RoundScore $ "/" $ ScoreLimit);

            if (KillerPRI.RoundScore >= ScoreLimit)
            {
                EndVersusMatch(KillerPlayer);
                return;
            }
        }
    }
    else
    {
        BroadcastMessage(Victim.PlayerReplicationInfo.PlayerName $ " went down.");
    }

    UpdateVersusGRI();
}

function RunVersusCharacterAuditProbe()
{
    local HPVersusHarry A;
    local HPVersusHarry B;
    local HPVersusCharacterAudit Audit;

    if (!bVersusMechanicsProbe || !bVersusMechanicsProbeComplete
        || bVersusCharacterAuditComplete)
        return;
    if (VersusInteractionArena != None
        && !VersusInteractionArena.bWorldProbeComplete)
        return;
    if (!GetVersusProbePlayers(A, B))
        return;

    Audit = Spawn(Class'HPVersusCharacterAudit');
    if (Audit == None)
    {
        Log("HPVersusCharacterAudit BLOCKED reason=spawn-failed");
        bVersusCharacterAuditComplete = True;
        return;
    }

    Audit.RunAudit(A);
    Audit.Destroy();
    bVersusCharacterAuditComplete = True;
}

function Timer()
{
    local Pawn P;
    local HPVersusHarry H;
    local HPVersusHarry ProbeA;
    local HPVersusHarry ProbeB;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None)
            continue;
        if (H.VersusSpeedBoostEndTime > 0.0
            && Level.TimeSeconds >= H.VersusSpeedBoostEndTime)
            H.ClearVersusSpeedBoost("GameTimerExpired");
        if (H.VersusSpellLockEndTime > 0.0
            && Level.TimeSeconds >= H.VersusSpellLockEndTime)
            H.VersusSpellLockEndTime = 0.0;
        if (H.VersusDisarmEndTime > 0.0
            && Level.TimeSeconds >= H.VersusDisarmEndTime)
            H.VersusDisarmEndTime = 0.0;
        if (H.bVersusSpongifyActive && H.Physics != PHYS_Falling)
            H.ClearVersusSpongify("ServerLanded");
    }

    if (CountVersusPlayers() < 2)
    {
        if (VersusPhase != 'WaitingForPlayers')
            EnterWaitingForPlayers();
    }
    else if (VersusPhase == 'WaitingForPlayers')
        BeginVersusCountdown();
    else if ((VersusPhase == 'Countdown' || VersusPhase == 'MatchOver')
        && Level.TimeSeconds >= PhaseEndTime)
        BeginVersusMatch();

    if (VersusPhase != 'MatchOver')
        RespawnDeadPlayers();
    UpdateVersusGRI();
    RunVersusMechanicsProbe();
    if (bVersusMechanicsProbe && bVersusMechanicsProbeComplete
        && VersusInteractionArena != None
        && GetVersusProbePlayers(ProbeA, ProbeB))
        VersusInteractionArena.RunWorldProbe(ProbeA, ProbeB);
    RunVersusCharacterAuditProbe();
}

function int CountVersusPlayers()
{
    local Pawn P;
    local HPVersusHarry H;
    local int Count;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H != None && H.Player != None)
            Count++;
    }
    return Count;
}

function EnterWaitingForPlayers()
{
    local HPVersusGRI G;

    bMatchInProgress = False;
    VersusPhase = 'WaitingForPlayers';
    PhaseEndTime = 0;
    G = HPVersusGRI(GameReplicationInfo);
    if (G != None)
        G.WinnerName = "";
    Log("HPVersusMatch phase=WaitingForPlayers players=" $ CountVersusPlayers());
}

function BeginVersusCountdown()
{
    bMatchInProgress = False;
    VersusPhase = 'Countdown';
    PhaseEndTime = Level.TimeSeconds + CountdownDuration;
    Log("HPVersusMatch phase=Countdown players=" $ CountVersusPlayers());
}

function BeginVersusMatch()
{
    local Pawn P;
    local HPVersusHarry H;
    local HPVersusPRI PRI;
    local HPVersusSpell Spell;
    local HPVersusGRI G;
    local bool bPreserveLiveCamera;
    local rotator SavedRotation;
    local rotator SavedDesiredRotation;
    local rotator SavedViewRotation;

    if (CountVersusPlayers() < 2)
    {
        EnterWaitingForPlayers();
        return;
    }

    // A Countdown begins because the missing opponent connected. Players
    // still return to their spawn locations, but their established view
    // direction must not snap to the map's PlayerStart rotation. MatchOver
    // restarts keep the normal clean round reset.
    bPreserveLiveCamera = VersusPhase == 'Countdown';
    bMatchInProgress = False;
    foreach AllActors(Class'HPVersusSpell', Spell)
        Spell.Destroy();
    ResetVersusPickups();
    if (VersusInteractionArena != None)
        VersusInteractionArena.ResetArena();

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None || H.Player == None)
            continue;

        PRI = HPVersusPRI(H.PlayerReplicationInfo);
        if (PRI != None)
        {
            PRI.RoundScore = 0;
            PRI.Score = 0;
            PRI.Deaths = 0;
        }
        if (bPreserveLiveCamera)
        {
            SavedRotation = H.Rotation;
            SavedDesiredRotation = H.DesiredRotation;
            SavedViewRotation = H.ViewRotation;
        }
        H.ResetVersusCombatEffects();
        if (RestartPlayer(H))
        {
            if (bPreserveLiveCamera)
            {
                H.SetRotation(SavedRotation);
                H.DesiredRotation = SavedDesiredRotation;
                H.ViewRotation = SavedViewRotation;
            }
            H.SetupVersusPlayer();
            H.VersusRespawnAt = 0;
            H.VersusRespawnSeconds = 0;
            H.ClientVersusRespawn(bPreserveLiveCamera);
        }
        else
        {
            H.bVersusDead = True;
            H.VersusRespawnAt = Level.TimeSeconds + 0.20;
            H.VersusRespawnSeconds = 0;
            H.GotoState('VersusDead');
            H.ClientVersusDeath();
        }
    }

    G = HPVersusGRI(GameReplicationInfo);
    if (G != None)
        G.WinnerName = "";
    VersusPhase = 'InProgress';
    PhaseEndTime = 0;
    bMatchInProgress = True;
    BroadcastMessage("Versus match started!");
    Log("HPVersusMatch phase=InProgress players=" $ CountVersusPlayers());
}

function RespawnDeadPlayers()
{
    local Pawn P;
    local HPVersusHarry H;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None || !H.bVersusDead || VersusPhase == 'MatchOver')
            continue;

        if (H.VersusRespawnAt > Level.TimeSeconds)
            H.VersusRespawnSeconds = byte(int(H.VersusRespawnAt - Level.TimeSeconds + 0.99));
        else
            H.VersusRespawnSeconds = 0;

        if (Level.TimeSeconds >= H.VersusRespawnAt)
        {
            if (RestartPlayer(H))
            {
                H.SetupVersusPlayer();
                H.VersusRespawnAt = 0;
                H.VersusRespawnSeconds = 0;
                H.ClientVersusRespawn();
            }
        }
    }
}

function EndVersusMatch(PlayerPawn Winner)
{
    if (VersusPhase != 'InProgress')
        return;

    bMatchInProgress = False;
    VersusPhase = 'MatchOver';
    PhaseEndTime = Level.TimeSeconds + MatchOverDuration;

    if (Winner != None && Winner.PlayerReplicationInfo != None)
    {
        BroadcastMessage("Versus winner: " $ Winner.PlayerReplicationInfo.PlayerName);

        if (GameReplicationInfo != None && GameReplicationInfo.IsA('HPVersusGRI'))
        {
            HPVersusGRI(GameReplicationInfo).bMatchOver = True;
            HPVersusGRI(GameReplicationInfo).WinnerName = Winner.PlayerReplicationInfo.PlayerName;
            HPVersusGRI(GameReplicationInfo).MatchState = 'VS_MatchOver';
        }
    }
    else
    {
        BroadcastMessage("Versus match ended.");
    }

    UpdateVersusGRI();
    Log("HPVersusMatch phase=MatchOver winner=" $ string(Winner)
        $ " nextMatchAt=" $ PhaseEndTime);
}

defaultproperties
{
    GameName="Harry Potter Versus"
    bTeamGame=False
    // bCoopGame is not a GameInfo var in this engine (mirrors sibling HPCoopGame);
    // a 1v1 versus mode is implicitly non-coop, so nothing is lost by omitting it.
    MaxPlayers=2
    ScoreLimit=3
    RespawnDelay=3.00
    CountdownDuration=3.00
    MatchOverDuration=5.00
    DefaultPlayerClass=Class'HGame.HPVersusHarry'
    GameReplicationInfoClass=Class'HGame.HPVersusGRI'
    // HPVersusHarry owns HPVersusPRI from spawn, preserving PlayerName/PlayerID.
    bDeathMatch=True
}

replacements.new:
//=============================================================================
// HPVersusGame.
//
// Free-for-all arena mode for 2 to 8 participants.
//
// Dedicated server (preferred first test, removes the listen-host Harry0 case):
//   UCC.exe server Arena.unr?game=HGame.HPVersusGame?MaxPlayers=2 -log=Server.log
// Listen host:
//   open Arena.unr?game=HGame.HPVersusGame?listen?MaxPlayers=2
// Join:
//   open <host-ip>
//
// The map must contain one HPVersusStart for every configured slot.
//=============================================================================

class HPVersusGame extends GameInfo;

var int ScoreLimit;
var float RespawnDelay;
var bool bMatchInProgress;
var name VersusPhase;
var float PhaseEndTime;
var float CountdownDuration;
var float MatchOverDuration;
var byte PendingLoginSlot;       // slot being used by the Login currently inside Super.Login()
var bool bHasPendingLoginSlot;
var HPVersusHealthPickup VersusHealthPickupA;
var HPVersusHealthPickup VersusHealthPickupB;
var HPVersusSpeedPickup VersusSpeedPickup;
var bool bVersusMechanicsProbe;
var bool bVersusMechanicsProbeComplete;
var byte VersusMechanicsProbeStage;
var float VersusMechanicsProbeNextTime;
var HPVersusSpongifyPad VersusProbeSpongifyPad;
var HPVersusSpongifyTarget VersusProbeSpongifyTarget;
var HPVersusInteractionArena VersusInteractionArena;
var bool bVersusCharacterAuditComplete;
var string VersusProbeCharacterA;
var string VersusProbeCharacterB;

function InitGame(string Options, out string Error)
{
    local string InOpt;

    Super.InitGame(Options, Error);
    if (MaxPlayers < 2)
        MaxPlayers = 2;
    if (MaxPlayers > 8)
        MaxPlayers = 8;

    InOpt = ParseOption(Options, "ScoreLimit");
    if (InOpt != "")
        ScoreLimit = int(InOpt);
    if (ScoreLimit < 1)
        ScoreLimit = 3;

    bVersusMechanicsProbe = ParseOption(Options, "VersusMechanicsProbe") ~= "1";

    Log("=== HPVersusGame loaded. ScoreLimit=" $ ScoreLimit
        $ " MechanicsProbe=" $ string(bVersusMechanicsProbe) $ " ===");
}

event PostBeginPlay()
{
    Super.PostBeginPlay();
    bMatchInProgress = False;
    VersusPhase = 'WaitingForPlayers';
    SetTimer(0.20, True);
    CleanupLegacyHarryActors();
    SpawnVersusDirector();
    SpawnVersusPickups();
    SpawnVersusInteractionArena();
    UpdateVersusGRI();
}

function bool IsVersusInteractionMap()
{
    return InStr(Caps(string(Level)), "HPV_INTERACTIONS") >= 0;
}

function SpawnVersusInteractionArena()
{
    if (Role != ROLE_Authority || !IsVersusInteractionMap())
        return;
    if (VersusInteractionArena == None)
        VersusInteractionArena = Spawn(
            Class'HPVersusInteractionArena',,,
            GetVersusPickupCenter(), rot(0,0,0));
    Log("HPVersusInteractionArena spawn actor="
        $ string(VersusInteractionArena)
        $ " level=" $ string(Level));
}

function Vector GetVersusPickupCenter()
{
    local HPVersusStart S;
    local Vector Center;
    local int Count;

    foreach AllActors(Class'HPVersusStart', S)
    {
        if (!S.bEnabled)
            continue;
        Center += S.Location;
        Count++;
    }
    if (Count > 0)
        Center = Center / float(Count);
    return Center;
}

function SpawnVersusPickups()
{
    local Vector Center;
    local Vector Offset;

    if (Role != ROLE_Authority)
        return;
    Center = GetVersusPickupCenter();

    Offset.X = -120.0;
    if (VersusHealthPickupA == None)
        VersusHealthPickupA = Spawn(
            Class'HPVersusHealthPickup',,, Center + Offset, rot(0,0,0));
    Offset.X = 120.0;
    if (VersusHealthPickupB == None)
        VersusHealthPickupB = Spawn(
            Class'HPVersusHealthPickup',,, Center + Offset, rot(0,0,0));
    Offset.X = 0.0;
    Offset.Y = 150.0;
    if (VersusSpeedPickup == None)
        VersusSpeedPickup = Spawn(
            Class'HPVersusSpeedPickup',,, Center + Offset, rot(0,0,0));

    Log("HPVersusPickups spawned healthA=" $ string(VersusHealthPickupA)
        $ " healthB=" $ string(VersusHealthPickupB)
        $ " speed=" $ string(VersusSpeedPickup)
        $ " center=" $ string(Center));
}

function ResetVersusPickups()
{
    if (VersusHealthPickupA == None
        || VersusHealthPickupB == None
        || VersusSpeedPickup == None)
        SpawnVersusPickups();
    if (VersusHealthPickupA != None)
        VersusHealthPickupA.ResetVersusPickup();
    if (VersusHealthPickupB != None)
        VersusHealthPickupB.ResetVersusPickup();
    if (VersusSpeedPickup != None)
        VersusSpeedPickup.ResetVersusPickup();
}

function bool GetVersusProbePlayers(out HPVersusHarry A, out HPVersusHarry B)
{
    local Pawn P;
    local HPVersusHarry H;

    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H == None || H.Player == None)
            continue;
        if (A == None)
            A = H;
        else if (H != A)
        {
            B = H;
            return True;
        }
    }
    return False;
}

function VersusProbeResult(bool bPassed, string CheckName)
{
    if (bPassed)
        Log("HPVersusMechanicsProbe PASS check=" $ CheckName);
    else
        Log("HPVersusMechanicsProbe FAIL check=" $ CheckName);
}

function RunVersusMechanicsProbe()
{
    local HPVersusHarry A;
    local HPVersusHarry B;
    local HPVersusFlipendo Flipendo;
    local HPVersusSpongify Spongify;
    local Vector ProbeLocation;
    local float RemainingCooldown;
    local HPVersusPRI ProbeAPRI;
    local HPVersusPRI ProbeBPRI;

    if (!bVersusMechanicsProbe || bVersusMechanicsProbeComplete
        || VersusPhase != 'InProgress'
        || Level.TimeSeconds < VersusMechanicsProbeNextTime
        || !GetVersusProbePlayers(A, B))
        return;

    if (VersusMechanicsProbeStage == 0)
    {
        Log("HPVersusMechanicsProbe START A=" $ string(A) $ " B=" $ string(B));
        ProbeAPRI = HPVersusPRI(A.PlayerReplicationInfo);
        ProbeBPRI = HPVersusPRI(B.PlayerReplicationInfo);
        if (ProbeAPRI != None)
            VersusProbeCharacterA = ProbeAPRI.SelectedCharacter;
        if (ProbeBPRI != None)
            VersusProbeCharacterB = ProbeBPRI.SelectedCharacter;
        A.ServerSelectVersusSpell(1);
        B.ServerSelectVersusSpell(3);
        VersusProbeResult(
            A.GetVersusSpellClass(A.SelectedVersusSpell) == Class'HPVersusMimblewimble'
            && B.GetVersusSpellClass(B.SelectedVersusSpell) == Class'HPVersusFlipendo'
            && A.GetVersusSpellClass(4) == Class'HPVersusAlohomora'
            && A.GetVersusSpellClass(5) == Class'HPVersusSpongify',
            "server-whitelist-selection");

        A.NextVersusServerCastTime = 0.0;
        A.ServerRequestCast(1.0, A.Rotation, A.GetVersusFallbackMuzzle(A.Rotation));
        RemainingCooldown = A.NextVersusServerCastTime - Level.TimeSeconds;
        VersusProbeResult(RemainingCooldown > 0.60 && RemainingCooldown < 0.80,
            "per-spell-server-cooldown");

        B.Health = 50;
        B.SetHealth(50);
        B.ClientSyncHealth(50);
        VersusHealthPickupA.RespawnTime = 0.50;
        VersusHealthPickupA.ResetVersusPickup();
        VersusHealthPickupA.TryPickup(B);
        VersusProbeResult(B.Health == 75 && !VersusHealthPickupA.bAvailable,
            "health-pickup-clamp-and-consume");

        VersusSpeedPickup.BoostDuration = 0.50;
        VersusSpeedPickup.ResetVersusPickup();
        VersusSpeedPickup.TryPickup(A);
        VersusProbeResult(A.IsVersusSpeedBoosted()
            && A.VersusSpeedMultiplier > 1.49,
            "speed-pickup-authority");

        B.HandleSpellDuelMimblewimble(None, B.Location);
        VersusProbeResult(B.Health == 67 && B.IsVersusSpellLocked(),
            "mimblewimble-damage-and-mute");
        B.HandleSpellDuelExpelliarmus(None, B.Location);
        VersusProbeResult(B.Health == 67 && B.VersusDisarmEndTime > Level.TimeSeconds,
            "expelliarmus-disarm-without-damage");

        ProbeLocation = B.Location;
        ProbeLocation.Z += 100.0;
        Flipendo = Spawn(Class'HPVersusFlipendo', A,, ProbeLocation, B.Rotation);
        if (Flipendo != None)
        {
            Flipendo.Instigator = A;
            Flipendo.SpellCharge = 1.0;
            Flipendo.Velocity = Normal(B.Location - A.Location) * Flipendo.Speed;
            Flipendo.OnSpellHitHarry(B, B.Location);
            Flipendo.Destroy();
        }
        VersusProbeResult(Flipendo != None && B.Health == 59
            && B.Physics == PHYS_Falling, "flipendo-damage-and-impulse");

        ProbeLocation = A.Location;
        ProbeLocation.Z += 8.0;
        VersusProbeSpongifyPad = Spawn(
            Class'HPVersusSpongifyPad',,, ProbeLocation, rot(0,0,0));
        ProbeLocation = A.Location;
        ProbeLocation.X += 180.0;
        ProbeLocation.Z += 80.0;
        VersusProbeSpongifyTarget = Spawn(
            Class'HPVersusSpongifyTarget',,, ProbeLocation, rot(0,0,0));
        if (VersusProbeSpongifyPad != None
            && VersusProbeSpongifyTarget != None)
        {
            VersusProbeSpongifyPad.Target = VersusProbeSpongifyTarget;
            VersusProbeSpongifyPad.fTimeToHitTarget = 2.0;
            Spongify = Spawn(Class'HPVersusSpongify', A,,
                VersusProbeSpongifyPad.Location, A.Rotation);
            if (Spongify != None)
            {
                Spongify.Instigator = A;
                Spongify.SpellCharge = 1.0;
                Spongify.OnSpellHitHPawn(
                    VersusProbeSpongifyPad,
                    VersusProbeSpongifyPad.Location);
                Spongify.Destroy();
            }
            VersusProbeSpongifyPad.OnBounce(A);
        }
        VersusProbeResult(Spongify != None
            && VersusProbeSpongifyPad != None
            && VersusProbeSpongifyPad.IsEnabled()
            && A.bVersusSpongifyActive
            && A.Physics == PHYS_Falling
            && VSize(A.Velocity) > 1.0,
            "spongify-authoritative-activation-and-bounce");

        VersusMechanicsProbeStage = 1;
        VersusMechanicsProbeNextTime = Level.TimeSeconds + 1.0;
        return;
    }

    if (VersusMechanicsProbeStage == 1)
    {
        VersusProbeResult(VersusHealthPickupA.bAvailable,
            "health-pickup-respawn-timer");
        VersusProbeResult(!A.IsVersusSpeedBoosted()
            && A.VersusSpeedMultiplier <= 1.01,
            "speed-expiry-reset");
        A.ApplyVersusSpeedBoost(1.5, 10.0);
        A.VersusKilledBy(B, 'MechanicsProbe');
        VersusProbeResult(A.bVersusDead && !A.IsVersusSpeedBoosted(),
            "death-clears-speed");
        VersusProbeResult(!A.bVersusSpongifyActive,
            "death-clears-spongify");
        VersusMechanicsProbeStage = 2;
        VersusMechanicsProbeNextTime = Level.TimeSeconds + RespawnDelay + 0.5;
        return;
    }

    VersusProbeResult(!A.bVersusDead && A.Health == 100
        && !A.IsVersusSpeedBoosted(), "respawn-restores-clean-state");
    ProbeAPRI = HPVersusPRI(A.PlayerReplicationInfo);
    ProbeBPRI = HPVersusPRI(B.PlayerReplicationInfo);
    VersusProbeResult(ProbeAPRI != None && ProbeBPRI != None
        && ProbeAPRI.SelectedCharacter ~= VersusProbeCharacterA
        && ProbeBPRI.SelectedCharacter ~= VersusProbeCharacterB
        && A.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterA)
        && B.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterB),
        "character-profile-survives-respawn");
    B.ApplyVersusSpeedBoost(1.5, 10.0);
    BeginVersusMatch();
    VersusProbeResult(!B.IsVersusSpeedBoosted() && B.Health == 100,
        "new-match-clears-speed");
    VersusProbeResult(ProbeAPRI.SelectedCharacter ~= VersusProbeCharacterA
        && ProbeBPRI.SelectedCharacter ~= VersusProbeCharacterB
        && A.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterA)
        && B.Mesh == class'HPVersusCharacterProfiles'.static.GetMesh(
            VersusProbeCharacterB),
        "character-profile-survives-new-match");
    if (VersusProbeSpongifyPad != None)
        VersusProbeSpongifyPad.Destroy();
    if (VersusProbeSpongifyTarget != None)
        VersusProbeSpongifyTarget.Destroy();
    bVersusMechanicsProbeComplete = True;
    Log("HPVersusMechanicsProbe COMPLETE");
}


function CleanupLegacyHarryActors()
{
    local harry H;

    foreach AllActors(Class'harry', H)
    {
        if (H == None)
            continue;

        if (HPVersusHarry(H) != None)
            continue;

        Log("HPVersusGame: destroying legacy single-player harry " $ string(H));
        H.Destroy();
    }
}

function SpawnVersusDirector()
{
    local Director D;

    foreach AllActors(Class'Director', D)
    {
        D.Destroy();
    }

    Spawn(Class'HPVersusDirector');
}

event PostLogin(PlayerPawn NewPlayer)
{
    local HPVersusHarry H;
    local harry LegacyHarry;
    local HPVersusPRI VPRI;

    Super.PostLogin(NewPlayer);

    H = HPVersusHarry(NewPlayer);
    if (H == None)
    {
        LegacyHarry = harry(NewPlayer);
        if (LegacyHarry != None)
        {
            Log("HPVersusGame: legacy host pawn logged in, enabling control: " $ string(NewPlayer));
            SetupLegacyHostPlayer(LegacyHarry);
        }
        else
        {
            Log("HPVersusGame: non-versus pawn logged in: " $ string(NewPlayer));
        }
        return;
    }

    VPRI = HPVersusPRI(NewPlayer.PlayerReplicationInfo);
    if (VPRI == None)
    {
        Log("HPVersusGame: expected HPVersusPRI for " $ string(NewPlayer));
        return;
    }
    VPRI.SetSelectedCharacter(VPRI.SelectedCharacter);
    H.ApplyCharacterSkin(VPRI.SelectedCharacter);
    H.SetupVersusPlayer();

    // Login assigns VersusSlot before Super.Login() so FindPlayerStart can pick
    // the correct HPVersusStart. Keep this fallback for old/listen edge cases.
    if (H.VersusSlot >= MaxPlayers)
        Log("HPVersusGame: invalid assigned slot=" $ H.VersusSlot);

    UpdateVersusGRI();

    Log("HPVersusGame: PostLogin player=" $ string(NewPlayer)
        $ " slot=" $ string(H.VersusSlot)
        $ " playerObj=" $ string(NewPlayer.Player)
        $ " loc=" $ string(NewPlayer.Location));

    BroadcastMessage(NewPlayer.PlayerReplicationInfo.PlayerName $ " joined Versus slot " $ H.VersusSlot $ " as " $ VPRI.SelectedCharacter);
}

function bool IsLocalViewportPlayer(PlayerPawn P)
{
    return P != None && P.Player != None && Viewport(P.Player) != None;
}

function SetupLegacyHostPlayer(harry H)
{
    if (H == None)
        return;

    H.bKeepStationary = False;
    H.bIsCaptured = False;
    H.bAllowHarryToDie = True;
    H.bCanMoveInSpecialPause = True;

    if (IsLocalViewportPlayer(H))
    {
        H.EnablePlayerInput();

        if (H.myHUD != None)
            H.myHUD.EndCutScene();

        if (H.Cam != None)
        {
            H.Cam.SetCameraMode(3);
            H.Cam.GotoState('StateStandardCam');
            H.Cam.InitTarget(H);
            H.Cam.InitPositionAndRotation(True);
        }
    }

    if (!H.IsInState('PlayerWalking'))
        H.GotoState('PlayerWalking');

    H.SetPhysics(PHYS_Walking);
    H.Health = 100;
}

//-----------------------------------------------------------------------------
// GRI wiring. Base GameInfo has no SetGRI(); it spawns GameReplicationInfoClass
// in PreBeginPlay and then calls InitGameReplicationInfo(). We override the
// latter to seed versus state on the spawned HPVersusGRI.
//-----------------------------------------------------------------------------

function InitGameReplicationInfo()
{
    Super.InitGameReplicationInfo();

    if (GameReplicationInfo != None && GameReplicationInfo.IsA('HPVersusGRI'))
    {
        HPVersusGRI(GameReplicationInfo).ScoreLimit = ScoreLimit;
        HPVersusGRI(GameReplicationInfo).MatchState = 'WaitingForPlayers';
        HPVersusGRI(GameReplicationInfo).bIsWarmup = True;
        HPVersusGRI(GameReplicationInfo).bIsRoundActive = False;
        HPVersusGRI(GameReplicationInfo).bMatchOver = False;
    }
}

function UpdateVersusGRI()
{
    local HPVersusGRI G;

    if (GameReplicationInfo == None)
        return;

    G = HPVersusGRI(GameReplicationInfo);
    if (G == None)
        return;

    G.ScoreLimit = ScoreLimit;
    G.bIsWarmup = VersusPhase == 'WaitingForPlayers' || VersusPhase == 'Countdown';
    G.bIsRoundActive = VersusPhase == 'InProgress';
    G.bMatchOver = VersusPhase == 'MatchOver';
    G.MatchState = VersusPhase;
    if (PhaseEndTime > Level.TimeSeconds)
        G.RoundTimer = int(PhaseEndTime - Level.TimeSeconds + 0.99);
    else
        G.RoundTimer = 0;
}

//-----------------------------------------------------------------------------
// Spawn selection. Base GameInfo.FindPlayerStart returns the FIRST
// bSinglePlayerStart for every joiner, which stacks both duelists on the map's
// vanilla Harry0 start. Pick an HPVersusStart by slot instead.
//-----------------------------------------------------------------------------

function NavigationPoint FindPlayerStart(Pawn Player, optional byte InTeam, optional string incomingName)
{
    local HPVersusStart S, Best;
    local HPVersusHarry Other;
    local byte Slot;
    local float Distance, Nearest, BestNearest;
    local bool bClear;

    if (HPVersusHarry(Player) != None)
        Slot = HPVersusHarry(Player).VersusSlot;
    else if (bHasPendingLoginSlot)
        Slot = PendingLoginSlot;

    foreach AllActors(Class'HPVersusStart', S)
    {
        if (!S.bEnabled || S.VersusSpawnIndex >= MaxPlayers)
            continue;

        bClear = True;
        Nearest = 1000000.0;
        foreach AllActors(Class'HPVersusHarry', Other)
        {
            if (Other == Player || !Other.bVersusRegistered || Other.bVersusDead)
                continue;
            Distance = VSize(Other.Location - S.Location);
            if (Distance < 96.0)
            {
                bClear = False;
                break;
            }
            if (Distance < Nearest)
                Nearest = Distance;
        }
        if (!bClear)
            continue;
        if (S.VersusSpawnIndex == Slot)
        {
            Best = S;
            break;
        }
        if (Best == None || Nearest > BestNearest)
        {
            Best = S;
            BestNearest = Nearest;
        }
    }

    if (Best != None)
    {
        Log("HPVersusGame: FindPlayerStart slot=" $ string(Slot) $ " start=" $ string(Best));
        return Best;
    }

    // RestartPlayer retries later if all starts are occupied. Never place an
    // arena pawn on the map's shared single-player start.
    return None;
}

function bool VersusStartIndexExists(byte Slot)
{
    local HPVersusStart S;
    foreach AllActors(Class'HPVersusStart', S)
        if (S.bEnabled && S.VersusSpawnIndex == Slot)
            return True;
    return False;
}

function Logout(Pawn Exiting)
{
    if (HPVersusHarry(Exiting) != None)
        HPVersusHarry(Exiting).bVersusRegistered = False;
    BroadcastMessage(string(Exiting) $ " left Versus");
    Super.Logout(Exiting);
}

function bool TooManyPlayers()
{
    local Pawn P;
    local HPVersusHarry H;
    local int Count;

    Count = 0;
    for (P = Level.PawnList; P != None; P = P.NextPawn)
    {
        H = HPVersusHarry(P);
        if (H != None && H.bVersusRegistered)
            Count++;
    }

    Log("HPVersusGame: connected player count=" $ Count $ " MaxPlayers=" $ MaxPlayers);
    return Count >= MaxPlayers || NumPlayers >= MaxPlayers;
}

function byte ChooseVersusSlot()
{
    local Pawn P;
    local HPVersusHarry H;
    local int Slot;
    local bool bUsed;

    for (Slot = 0; Slot < MaxPlayers; Slot++)
    {
        bUsed = False;
        for (P = Level.PawnList; P != None; P = P.NextPawn)
        {
            H = HPVersusHarry(P);
            if (H != None && H.bVersusRegistered && H.VersusSlot == Slot)
            {
                bUsed = True;
                break;
            }
        }
        if (!bUsed && VersusStartIndexExists(byte(Slot)))
            return byte(Slot);
    }
    return 255;
}

event PlayerPawn Login
(
    string Portal,
    string Options,
    out string Error,
    class<playerpawn> SpawnClass
)
{
    local PlayerPawn NewPlayer;
    local HPVersusHarry H;
    local HPVersusPRI VPRI;
    local byte LoginSlot;
    local string LoginCharacter;

    if (TooManyPlayers())
    {
        Error = "Versus server is full.";
        return None;
    }

    // Clients still send their single-player class in the URL
    // (usually Class=HGame.harry). Force the arena pawn so each
    // connection gets its own controllable versus player.
    SpawnClass = Class'HPVersusHarry';
    LoginSlot = ChooseVersusSlot();
    if (LoginSlot == 255)
    {
        Error = "No free Versus start for this server capacity.";
        return None;
    }
    PendingLoginSlot = LoginSlot;
    bHasPendingLoginSlot = True;

    Log("HPVersusGame: Login forcing SpawnClass=HPVersusHarry slot=" $ string(LoginSlot)
        $ " portal=" $ Portal $ " options=" $ Options);

    NewPlayer = Super.Login(Portal, Options, Error, SpawnClass);

    bHasPendingLoginSlot = False;

    H = HPVersusHarry(NewPlayer);
    if (H != None)
    {
        LoginCharacter = "Harry";
        VPRI = HPVersusPRI(H.PlayerReplicationInfo);
        if (VPRI != None)
        {
            VPRI.SetSelectedCharacter(ParseOption(Options, "MPCharacter"));
            H.ApplyCharacterSkin(VPRI.SelectedCharacter);
            LoginCharacter = VPRI.SelectedCharacter;
        }
        H.VersusSlot = LoginSlot;
        H.bVersusRegistered = True;
        H.ClientSetVersusSlot(LoginSlot);
        Log("HPVersusGame: Login assigned player=" $ string(H)
            $ " slot=" $ string(H.VersusSlot)
            $ " character=" $ LoginCharacter
            $ " playerObj=" $ string(H.Player)
            $ " loc=" $ string(H.Location));
    }

    return NewPlayer;
}

