simulated event PostNetBeginPlay()
{
    // Do not call the multiplayer workaround appended to harry.uc. Its
    // Role<Authority guard also accepts remote SimulatedProxy pawns and lets
    // them retarget the client's shared BaseCam to themselves. Keep only the
    // original simulated PlayerPawn/Pawn network initialization. Remote proxy
    // pawns stop here; only the autonomous owner/authority may run the versus
    // camera, input and spell bootstrap.
    Super(PlayerPawn).PostNetBeginPlay();
    Log("HPVersusBuild version=16 phase=PostNetBeginPlay pawn=" $ string(self)
        $ " Role=" $ string(Role) $ " NetMode=" $ string(Level.NetMode));

    if (Role < ROLE_AutonomousProxy)
    {
        // HP2 skeletal meshes normally rely on the engine's bottom-alignment
        // pass. A non-owner network Harry is a PHYS_None SimulatedProxy and
        // does not receive the same pawn update path as the locally possessed
        // copy. Force the native "always" variant only on this visual proxy;
        // Location, Physics, collision and the owning player remain untouched.
        bAlignBottom = True;
        bAlignBottomAlways = True;

        Log("HPVersusRemoteBottomAlign phase=PostNetBeginPlay pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " Role=" $ string(Role)
            $ " PrePivot=" $ string(PrePivot)
            $ " SavedPrePivotZ=" $ string(SavedPrePivotZ)
            $ " bAlignBottom=" $ string(bAlignBottom)
            $ " bAlignBottomAlways=" $ string(bAlignBottomAlways));

        // A SimulatedProxy never runs Harry's single-player states or
        // cHarryAnimChannel.  Give it only the visual-only upper-body channel;
        // camera, input, cursor and gameplay bootstrap remain owner-only.
        LastSeenVersusCastSerial = VersusCastSerial;
        EnsureVersusRemoteAnimationChannel("PostNetBeginPlay");
        EnsureVersusPlayerAnimationSet();
        UpdateVersusCloakAnimation();
        return;
    }

    SetupVersusPlayer();
}

