}

function SetupVersusPlayer()
{
    local bool bLocalPlayer;

    bLocalPlayer = IsLocalViewportPlayer();
    if (bLocalPlayer)
        ResetVersusFreeLook("Setup");

    bKeepStationary = False;
    bIsCaptured = False;
    bAllowHarryToDie = True;
    bHidden = False;
    SetCollision(True, True, True);
    bCanMoveInSpecialPause = True;
    bVersusDead = False;
    bFrozen = False;

    if (bLocalPlayer)
    {
        CleanupLocalLegacyHarry();
        Level.PlayerHarryActor = self;
        EnablePlayerInput();
        EnsureVersusAnimationChannel("SetupVersusPlayer");
        EnsureVersusPlayerAnimationSet();
        UpdateVersusCloakAnimation();

        if (!bVersusMovementChoiceMade)
        {
            Log("HPVersusMovementAuto pawn=" $ string(self) $ " mode=Native");
            SetVersusEngineMovement(True);
        }

        if (myHUD != None)
            myHUD.EndCutScene();
    }

    if (!IsInState('PlayerWalking'))
        GotoState('PlayerWalking');

    SetPhysics(PHYS_Walking);
    Health = 100;
    SetHealth(100);

    // Server grants and explicitly selects one owner-scoped versus wand per
    // pawn.  A copied legacy baseWand no longer suppresses this grant.
    if (Role == ROLE_Authority)
        EnsureServerVersusWand();

    // Camera: route through the safety shim so ONLY the local viewport pawn
    // ever touches the shared BaseCam. During the first Countdown -> live
    // transition keep the established orbit instead of hard-resetting it to
    // the PlayerStart rotation merely because the second player connected.
    if (bPreserveVersusCameraOnSetup)
        class'HPVersusCamera'.static.ApplyStandardCam(self);
    else
        class'HPVersusCamera'.static.ForceStandardCam(self);
    SetupVersusSpellObjects("SetupVersusPlayer");
}

