simulated function KeepVersusBodyUpright()
{
    local rotator BodyRotation;
    local rotator SourceRotation;

    // PlayerPawn.ServerMove carries the compressed camera pitch/client roll
    // through the pawn's Actor.Rotation. That is appropriate for aim-capable
    // stock pawns, but HP2 renders Harry's whole skeletal mesh from this
    // rotation. Non-owner clients then see the complete body orbit its mesh
    // pivot when the owner looks vertically. Keep aim in ViewRotation and
    // replicate an upright presentation transform instead.
    DesiredRotation.Pitch = 0;
    DesiredRotation.Roll = 0;

    if (Rotation.Pitch == 0 && Rotation.Roll == 0)
        return;

    SourceRotation = Rotation;
    BodyRotation = SourceRotation;
    BodyRotation.Pitch = 0;
    BodyRotation.Roll = 0;
    SetRotation(BodyRotation);

    if (Role == ROLE_Authority && Level.TimeSeconds >= NextVersusBodyTraceTime)
    {
        Log("HPVersusBodyUpright pawn=" $ string(self)
            $ " oldRotation=" $ string(SourceRotation)
            $ " newRotation=" $ string(Rotation)
            $ " ViewRotation=" $ string(ViewRotation));
        NextVersusBodyTraceTime = Level.TimeSeconds + 0.25;
    }
}

simulated function UpdateVersusProxyPresentation()
{
    local string RemoteChannelState;
    local string RemoteChannelAnim;
    local string RemoteChannelFrame;
    local string RemoteChannelRate;

    if (Role != ROLE_SimulatedProxy)
        return;

    // Keep this local presentation flag asserted on the established proxy
    // update path as well as at PostNetBeginPlay. It is never applied to the
    // owner or authority and cannot affect the replicated actor transform.
    bAlignBottom = True;
    bAlignBottomAlways = True;

    // ServerMove may transiently carry view pitch in Actor.Rotation.  The
    // authority already strips it, and this local guard prevents one received
    // frame from rotating Harry's complete mesh around its centre.
    KeepVersusBodyUpright();
    EnsureVersusRemoteAnimationChannel("ObserverPlayerInput");

    // Cast is an upper-body cHarryAnimChannel animation on the owner and is
    // absent from UE1's replicated base AnimSequence/SimAnim.  Consume the
    // authority serial once on each observing proxy, through a channel that
    // has no Cast(), cursor or weapon callbacks.
    if (VersusCastSerial != LastSeenVersusCastSerial)
    {
        if (PlayVersusRemoteCast())
            LastSeenVersusCastSerial = VersusCastSerial;
    }

    RestoreVersusRemoteBaseAnimation();

    if (Level.TimeSeconds >= NextVersusProxyTraceTime)
    {
        if (VersusRemoteAnimChannel == None)
        {
            RemoteChannelState = "None";
            RemoteChannelAnim = "None";
            RemoteChannelFrame = "None";
            RemoteChannelRate = "None";
        }
        else
        {
            RemoteChannelState = string(VersusRemoteAnimChannel.GetStateName());
            RemoteChannelAnim = string(VersusRemoteAnimChannel.AnimSequence);
            RemoteChannelFrame = string(VersusRemoteAnimChannel.AnimFrame);
            RemoteChannelRate = string(VersusRemoteAnimChannel.AnimRate);
        }

        Log("HPVersusProxyState pawn=" $ string(self)
            $ " phase=ObserverPlayerInput"
            $ " time=" $ string(Level.TimeSeconds)
            $ " slot=" $ string(VersusSlot)
            $ " Role=" $ string(Role)
            $ " RemoteRole=" $ string(RemoteRole)
            $ " Physics=" $ string(Physics)
            $ " Base=" $ string(Base)
            $ " Location=" $ string(Location)
            $ " PrePivot=" $ string(PrePivot)
            $ " SavedPrePivotZ=" $ string(SavedPrePivotZ)
            $ " bAlignBottom=" $ string(bAlignBottom)
            $ " bAlignBottomAlways=" $ string(bAlignBottomAlways)
            $ " Velocity=" $ string(Velocity)
            $ " Acceleration=" $ string(Acceleration)
            $ " Rotation=" $ string(Rotation)
            $ " AnimSequence=" $ string(AnimSequence)
            $ " AnimFrame=" $ string(AnimFrame)
            $ " AnimRate=" $ string(AnimRate)
            $ " castSerial=" $ string(VersusCastSerial)
            $ " lastCastSerial=" $ string(LastSeenVersusCastSerial)
            $ " remoteChannel=" $ string(VersusRemoteAnimChannel)
            $ " remoteChannelState=" $ RemoteChannelState
            $ " remoteChannelAnim=" $ RemoteChannelAnim
            $ " remoteChannelFrame=" $ RemoteChannelFrame
            $ " remoteChannelRate=" $ RemoteChannelRate);
        NextVersusProxyTraceTime = Level.TimeSeconds + 0.50;
    }
}

