simulated function EnsureVersusPlayerAnimationSet()
{
    // Profiles keep one gameplay pawn and one accepted movement pipeline.
    // Compatible cosmetic meshes are linked to the complete Harry player
    // animation set instead of inheriting partial NPC state animations.
    if (class'HPVersusCharacterProfiles'.static.ShouldLinkHarryAnimations(Mesh)
        && SkelAnim != Animation'HPModels.skHarryAnims')
    {
        LinkSkelAnim(Animation'HPModels.skHarryAnims');
    }
}

simulated function bool EnsureVersusCloakAnimationChannels()
{
    local bool bFemale;
    local bool bCreated;
    local byte CloakStrategy;
    local name CloakRoot1;
    local name CloakRoot2;
    local int CloakBone1;
    local int CloakBone2;

    CloakStrategy = class'HPVersusCharacterProfiles'.static.GetCloakStrategy(Mesh);
    if (CloakStrategy == 0)
        return False;

    bFemale = CloakStrategy == 2;
    CloakRoot1 = name("~Cloak01");
    CloakRoot2 = name("~Cloak02");
    CloakBone1 = BoneNumber(CloakRoot1);
    CloakBone2 = BoneNumber(CloakRoot2);

    if (!bVersusCloakProbeLogged)
    {
        bVersusCloakProbeLogged = True;
        Log("HPVersusCloak roots pawn=" $ string(self)
            $ " mesh=" $ string(Mesh)
            $ " strategy=" $ string(CloakStrategy)
            $ " root1=" $ string(CloakRoot1) $ ":" $ string(CloakBone1)
            $ " root2=" $ string(CloakRoot2) $ ":" $ string(CloakBone2));
    }

    if (VersusCloakChannel1 == None && CloakBone1 >= 0)
    {
        VersusCloakChannel1 = HPVersusCloakAnimChannel(CreateAnimChannel(
            Class'HPVersusCloakAnimChannel', AT_Replace, CloakRoot1, False, True));
        if (VersusCloakChannel1 != None)
        {
            VersusCloakChannel1.SetOwner(self);
            bCreated = True;
        }
    }

    if (VersusCloakChannel2 == None && CloakBone2 >= 0)
    {
        VersusCloakChannel2 = HPVersusCloakAnimChannel(CreateAnimChannel(
            Class'HPVersusCloakAnimChannel', AT_Replace, CloakRoot2, False, True));
        if (VersusCloakChannel2 != None)
        {
            VersusCloakChannel2.SetOwner(self);
            bCreated = True;
        }
    }

    if (VersusCloakChannel1 == None || VersusCloakChannel2 == None)
        return False;

    if (!bVersusCloakConfigured || bVersusCloakFemale != bFemale)
    {
        VersusCloakChannel1.Configure(bFemale);
        VersusCloakChannel2.Configure(bFemale);
        bVersusCloakConfigured = True;
        bVersusCloakFemale = bFemale;
        LastVersusCloakAnim = 'None';

        Log("HPVersusCloak configured pawn=" $ string(self)
            $ " mesh=" $ string(Mesh)
            $ " female=" $ string(bFemale)
            $ " channel1=" $ string(VersusCloakChannel1)
            $ " channel2=" $ string(VersusCloakChannel2));
    }
    else if (bCreated)
    {
        LastVersusCloakAnim = 'None';
    }

    return True;
}

simulated function name GetVersusCloakAnimation()
{
    if (Physics == PHYS_Falling || IsVersusJumpOrFallAnim(AnimSequence)
        || AnimSequence == HarryAnims[HarryAnimSet].Land)
        return 'run';

    if (AnimSequence == HarryAnims[HarryAnimSet].StrafeLeft
        || AnimSequence == 'strafe_left')
        return 'strafe_left';

    if (AnimSequence == HarryAnims[HarryAnimSet].StrafeRight
        || AnimSequence == 'strafe_right')
        return 'strafe_right';

    if (AnimSequence == HarryAnims[HarryAnimSet].WalkBack
        || AnimSequence == 'duel_runback')
        return 'duel_runback';

    if (IsVersusMovementAnim(AnimSequence))
        return 'run';

    if (AnimSequence == 'faint')
        return 'faint';

    return 'Idle';
}

simulated function UpdateVersusCloakAnimation()
{
    local name CloakAnim;
    local bool bLooping;

    if (!EnsureVersusCloakAnimationChannels())
        return;

    CloakAnim = GetVersusCloakAnimation();
    bLooping = CloakAnim != 'faint';
    if (CloakAnim == LastVersusCloakAnim && bLooping == bLastVersusCloakLoop)
        return;

    if (!VersusCloakChannel1.PlayCloakAnimation(CloakAnim, bLooping)
        || !VersusCloakChannel2.PlayCloakAnimation(CloakAnim, bLooping))
    {
        Log("HPVersusCloak missing animation pawn=" $ string(self)
            $ " requested=" $ string(CloakAnim)
            $ " mesh=" $ string(Mesh));
        return;
    }

    LastVersusCloakAnim = CloakAnim;
    bLastVersusCloakLoop = bLooping;
    Log("HPVersusCloak animation pawn=" $ string(self)
        $ " body=" $ string(AnimSequence)
        $ " cloak=" $ string(CloakAnim)
        $ " looping=" $ string(bLooping));
}


function ClearVersusInput()
{
    bVersusMoveForward = 0;
    bVersusMoveBack = 0;
    bVersusMoveLeft = 0;
    bVersusMoveRight = 0;
    bVersusJump = 0;
    bVersusJumpWasDown = 0;
}

function name GetVersusDesiredMovementAnim()
{
    local rotator MoveRotation;
    local vector X;
    local vector Y;
    local vector Z;
    local vector Dir;

    // Prefer the actual local button intent before the physics update turns
    // the pawn. This prevents S from being reclassified as forward running.
    if (IsLocalViewportPlayer())
    {
        if (bVersusMoveBack != 0 && bVersusMoveForward == 0)
            return HarryAnims[HarryAnimSet].WalkBack;

        if (bVersusMoveForward == 0 && bVersusMoveLeft != 0 && bVersusMoveRight == 0)
            return HarryAnims[HarryAnimSet].StrafeLeft;

        if (bVersusMoveForward == 0 && bVersusMoveRight != 0 && bVersusMoveLeft == 0)
            return HarryAnims[HarryAnimSet].StrafeRight;
    }

    // Authority has no local key state, so classify acceleration relative to
    // the replicated view/camera direction instead of the pawn body rotation.
    MoveRotation = GetVersusMoveRotation();
    GetAxes(MoveRotation, X, Y, Z);
    Dir = Normal(Acceleration);

    if ((Dir Dot X < 0.75) && (Dir != vect(0.00,0.00,0.00)))
    {
        if (Dir Dot X < -0.75)
        {
            if (UsesVersusGenericAnimationSet())
                return 'duel_runback';

            return HarryAnims[HarryAnimSet].WalkBack;
        }

        if (Dir Dot Y > 0)
        {
            if (UsesVersusGenericAnimationSet())
                return 'strafe_right';

            return HarryAnims[HarryAnimSet].StrafeRight;
        }

        if (UsesVersusGenericAnimationSet())
            return 'strafe_left';

        return HarryAnims[HarryAnimSet].StrafeLeft;
    }

    if (UsesVersusGenericAnimationSet())
        return 'run';

    return HarryAnims[HarryAnimSet].run;
}

function bool UsesVersusGenericAnimationSet()
{
    return Mesh == SkeletalMesh'HPModels.skronMesh'
        || Mesh == SkeletalMesh'HPModels.skhermioneMesh';
}

function bool IsVersusJumpOrFallAnim(name SequenceName)
{
    return SequenceName == HarryAnims[HarryAnimSet].Jump
        || SequenceName == HarryAnims[HarryAnimSet].Jump2
        || SequenceName == HarryAnims[HarryAnimSet].Fall
        || SequenceName == AnimFalling;
}

function bool IsVersusMovementAnim(name SequenceName)
{
    return SequenceName == HarryAnims[HarryAnimSet].run
        || SequenceName == HarryAnims[HarryAnimSet].Walk
        || SequenceName == HarryAnims[HarryAnimSet].WalkBack
        || SequenceName == HarryAnims[HarryAnimSet].StrafeRight
        || SequenceName == HarryAnims[HarryAnimSet].StrafeLeft
        || SequenceName == 'duel_runback'
        || SequenceName == 'strafe_right'
        || SequenceName == 'strafe_left';
}

function TweenToRunning(float TweenTime)
{
    local name DesiredAnim;

    BaseEyeHeight = Default.BaseEyeHeight;
    if (!EnsureVersusAnimationChannel("TweenToRunning"))
        return;
    if (!HarryAnimChannel.PlayHarryMovementAnims())
        return;

    DesiredAnim = GetVersusDesiredMovementAnim();
    if (!HasAnim(DesiredAnim))
        DesiredAnim = HarryAnims[HarryAnimSet].run;

    LoopAnim(DesiredAnim, 0.89999998, TweenTime,, HarryAnimType);
    bMovingBackwards = DesiredAnim == HarryAnims[HarryAnimSet].WalkBack
        || DesiredAnim == 'duel_runback';
}

function ReconcileVersusMovementAnimation(string Phase)
{
    local float Speed;
    local float AccelSize;
    local name DesiredAnim;
    local name PreviousAnim;

    // Owner needs local prediction because animation is not echoed back over
    // its autonomous channel. Native-movement authority must publish the same
    // decision for non-owner simulated proxies. Never run this classifier on
    // the proxy: replicated Velocity is useful there, but Acceleration is not
    // reliable. Keep the proven Direct server fallback unchanged as well.
    if (!IsLocalViewportPlayer()
        && (Role != ROLE_Authority || !bUseEngineNetworkMovement))
        return;

    if (!IsInState('PlayerWalking'))
        return;

    if (bVersusDead || Health <= 0 || bJustFired || bJustAltFired)
        return;

    if (!EnsureVersusAnimationChannel(Phase))
        return;

    if (!HarryAnimChannel.PlayHarryMovementAnims())
        return;

    // DoJump, ProcessFalling and Landed retain ownership of the airborne
    // sequence.  Recovery below starts only after physics reports walking.
    if (Physics == PHYS_Falling)
        return;

    if (Physics != PHYS_Walking)
        return;

    Speed = VSize2D(Velocity);
    AccelSize = VSize2D(Acceleration);
    PreviousAnim = AnimSequence;

    // Preserve the landing pause only while Land is still playing. On a
    // server autonomous pawn the completed sequence can stay at AnimRate=0
    // without the expected AnimEnd -> waiting transition. Do not leave that
    // finished Land published indefinitely to observing clients.
    if (AnimSequence == HarryAnims[HarryAnimSet].Land
        && (Speed < 5.0 || AccelSize <= 1.0)
        && AnimRate != 0.0)
        return;

    // During W<->S/A<->D reversal Speed crosses zero for one frame while the
    // new Acceleration is already valid. If a movement loop is active, switch
    // direction directly instead of publishing an intermediate Idle/reset.
    if (AccelSize > 1.0
        && (Speed > 5.0 || IsVersusMovementAnim(AnimSequence)))
    {
        DesiredAnim = GetVersusDesiredMovementAnim();
        if (AnimSequence != DesiredAnim || AnimRate <= 0.0)
        {
            bAnimTransition = False;
            TweenToRunning(0.15);
        }
    }
    else if (((AccelSize <= 1.0 && Speed < 5.0)
            && IsVersusMovementAnim(AnimSequence))
        || IsVersusJumpOrFallAnim(AnimSequence)
        || (AnimSequence == HarryAnims[HarryAnimSet].Land && AnimRate == 0.0)
        || (AccelSize <= 1.0 && AnimRate <= 0.0))
    {
        // A completed jump can remain on its last frame on an autonomous
        // proxy because the owner's AnimSequence is not echoed by the server.
        bAnimTransition = False;
        TweenToWaiting(0.15);
    }

    if (AnimSequence != PreviousAnim && Level.TimeSeconds >= NextVersusAnimTraceTime)
    {
        Log("HPVersusAnimReconcile phase=" $ Phase
            $ " pawn=" $ string(self)
            $ " time=" $ string(Level.TimeSeconds)
            $ " slot=" $ string(VersusSlot)
            $ " Role=" $ string(Role)
            $ " physics=" $ string(Physics)
            $ " speed=" $ string(Speed)
            $ " acceleration=" $ string(Acceleration)
            $ " old=" $ string(PreviousAnim)
            $ " new=" $ string(AnimSequence)
            $ " rate=" $ string(AnimRate));
        NextVersusAnimTraceTime = Level.TimeSeconds + 0.10;
    }
}

