    bUseEngineNetworkMovement = bEnable;
    Acceleration = vect(0.00,0.00,0.00);

    Log("HPVersusMovementMode pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " side=server"
        $ " mode=" $ VersusMovementModeName()
        $ " Role=" $ string(Role)
        $ " RemoteRole=" $ string(RemoteRole));
