exec function VersusClearInput()
{
    ClearVersusInput();
    ClientMessage("Versus input cleared");
    Log("Versus input cleared pawn=" $ string(self));
}

exec function VersusNudgeForward(optional float Dist)
{
    local vector X;
    local vector Y;
    local vector Z;
    local vector D;

    if (Dist == 0.0)
        Dist = 80.0;

    GetAxes(Rotation, X, Y, Z);
    D = X * Dist;

    // Client-side immediate feedback, then server authority.
    SetLocation(Location + D);

    if (Role < ROLE_Authority)
        ServerVersusNudge(D.X, D.Y, D.Z);
}

function ServerVersusNudge(float DX, float DY, float DZ)
{
    local vector D;

    if (Role != ROLE_Authority)
        return;

    D.X = DX;
    D.Y = DY;
    D.Z = DZ;
    SetLocation(Location + D);

    Log("ServerVersusNudge pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " d=" $ string(D)
        $ " loc=" $ string(Location));
}

event PlayerInput(float DeltaTime)
{
    local HPVersusHarry ObservedHarry;

    if (IsLocalViewportPlayer() && !bVersusMovementChoiceMade)
    {
        Log("HPVersusMovementAuto pawn=" $ string(self) $ " mode=Native");
        SetVersusEngineMovement(True);
    }

    if (bVersusDead)
    {
        ClearVersusInput();
        return;
    }

    if (IsLocalViewportPlayer())
    {
        Level.PlayerHarryActor = self;
        bKeepStationary = False;
        bIsCaptured = False;
        // The camera is already bound before Alt begins. Do not call even
        // InitTarget/Stabilize paths each held frame; keep only the viewport.
        if (bVersusFreeLook == 0 && !bVersusFreeLookActive)
            class'HPVersusCamera'.static.ApplyStandardCam(self);
        ForceVersusViewTarget();
        SetupVersusSpellObjects("PlayerInput");
    }

    Super.PlayerInput(DeltaTime);
    UpdateVersusFreeLook();
    ApplyVersusInput(DeltaTime);

    // Network PlayerPawn tick dispatch differs from ordinary actors. Drive
    // visual-only proxies from this viewport's proven input callback, even
    // while its keys are released. Never run their owner/bootstrap methods.
    if (IsLocalViewportPlayer())
    {
        foreach AllActors(Class'HPVersusHarry', ObservedHarry)
            if (ObservedHarry != self && ObservedHarry.Role == ROLE_SimulatedProxy)
                ObservedHarry.UpdateVersusProxyPresentation();
    }
}

function Timer()
{
    // Do not call harry.Timer(): it restores Health to 100 every second AND
    // re-forces the camera, both of which make a duel impossible and fight the
    // host camera. Keep only the animation timer.
    SleepyAnimTimerSub();
}

function SetHealth(int iHealth)
{
    Health = iHealth;
}

function AddHealth(int iHealth)
{
    Health += iHealth;

    if (Health < 0)
        Health = 0;
}

function int GetHealthCount()
{
    return Health;
}

function int VersusDamage(int MinDamage, int Damage)
{
    if (Damage < MinDamage)
        return MinDamage;

    return Damage;
}

function KillHarry(bool bImmediateDeath)
{
    if (Role != ROLE_Authority)
        return;

    VersusKilledBy(None, 'Killed');
}

function KillHarryWithClub(bool bImmediateDeath, Actor A)
{
    if (Role != ROLE_Authority)
        return;

    VersusKilledBy(Pawn(A), 'Club');
}

function Died(Pawn Killer, name DamageType, Vector HitLocation)
{
    if (Role != ROLE_Authority)
        return;

    VersusKilledBy(Killer, DamageType);
}

function TakeDamage(int Damage, Pawn InstigatedBy, vector HitLocation, vector Momentum, name DamageType)
{
    local int OldHealth;

    if (Role != ROLE_Authority)
        return;
    if (HPVersusGame(Level.Game) != None && !HPVersusGame(Level.Game).bMatchInProgress)
        return;

    if (bVersusDead)
        return;

    if (Damage <= 0)
        return;

    OldHealth = Health;
    AddHealth(-Damage);
    if (Health > 100)
        Health = 100;
    LastVersusHitTime = Level.TimeSeconds;
    ClientSyncHealth(Health);

    Log("HPVersusDamage victim=" $ string(self)
        $ " victimSlot=" $ string(VersusSlot)
        $ " instigator=" $ string(InstigatedBy)
        $ " damage=" $ string(Damage)
        $ " oldHealth=" $ string(OldHealth)
        $ " newHealth=" $ string(Health)
        $ " type=" $ string(DamageType)
        $ " hit=" $ string(HitLocation));

    if (Health <= 0 || GetHealthCount() <= 0)
    {
        VersusKilledBy(InstigatedBy, DamageType);
        return;
    }

    PlayHurtEmoteSound();
    HarryKnockBack();
}

function bool HandleSpellDuelRictusempra(optional baseSpell spell, optional Vector vHitLocation)
{
    local int Damage;

    if (Role != ROLE_Authority)
        return False;

    if (spell == None)
        TakeDamage(15, None, Location, vect(0.00,0.00,0.00), 'DuelRictusempra');
    else {
        Damage = VersusDamage(5, int(15 * spell.SpellCharge));
        TakeDamage(Damage, Pawn(spell.Owner), vHitLocation, vect(0.00,0.00,0.00), 'DuelRictusempra');
    }

    return True;
}

function bool HandleSpellDuelMimblewimble(optional baseSpell spell, optional Vector vHitLocation)
{
    local int Damage;
    local float Charge;
    local Pawn Attacker;

    if (Role != ROLE_Authority)
        return False;

    Charge = 1.0;
    if (spell != None)
    {
        Charge = FClamp(spell.SpellCharge, 0.0, 1.0);
        Attacker = Pawn(spell.Owner);
    }
    Damage = VersusDamage(3, int(8 * Charge));
    TakeDamage(Damage, Attacker, vHitLocation,
        vect(0.00,0.00,0.00), 'DuelMimblewimble');
    if (!bVersusDead)
        ApplyVersusSpellLock(0.75 + 0.75 * Charge);

    return True;
}

function bool HandleSpellDuelExpelliarmus(optional baseSpell spell, optional Vector vHitLocation)
{
    local float Charge;

    if (Role != ROLE_Authority || bVersusDead)
        return False;

    Charge = 1.0;
    if (spell != None)
        Charge = FClamp(spell.SpellCharge, 0.0, 1.0);

    // Stock duelists cast Expelliarmus as a timed defence when an incoming
    // spell is close. In FFA the corresponding minimal network mechanic is a
    // non-damaging cast interruption plus a short authoritative disarm window.
    ApplyVersusDisarm(0.45 + 0.45 * Charge);
    return True;
}

function VersusKilledBy(Pawn Killer, name DamageType)
{
    local HPVersusGame VG;

    if (bVersusDead)
        return;

    bVersusDead = True;
    Health = 0;
    SetHealth(0);
    ResetVersusCombatEffects();
    ClearVersusInput();
    GotoState('VersusDead');
    ClientVersusDeath();

    VG = HPVersusGame(Level.Game);
    if (VG != None)
        VG.NotifyVersusDeath(self, Killer, DamageType);
}

function ClientVersusDeath()
{
    ResetVersusFreeLook("Death");
    bVersusDead = True;
    Health = 0;
    ResetVersusCombatEffects();
    ClearVersusInput();
    GotoState('VersusDead');
}

function ClientVersusRespawn(optional bool bPreserveLiveCamera)
{
    bVersusDead = False;
    bPreserveVersusCameraOnSetup = bPreserveLiveCamera
        && IsLocalViewportPlayer() && Cam != None;
    SetupVersusPlayer();
    bPreserveVersusCameraOnSetup = False;
}

function ClientSyncHealth(int NewHealth)
{
    local StatusItem HealthItem;

    Health = Clamp(NewHealth, 0, 100);
    HealthItem = GetHealthStatusItem();
    if (HealthItem != None)
        HealthItem.SetCount(Health);
}

function bool HealVersus(int Amount)
{
    local int NewHealth;

    if (Role != ROLE_Authority || bVersusDead || Health <= 0 || Health >= 100)
        return False;
    if (Amount <= 0)
        return False;
    NewHealth = Min(100, Health + Amount);
    if (NewHealth <= Health)
        return False;
    Health = NewHealth;
    SetHealth(NewHealth);
    ClientSyncHealth(NewHealth);
    Log("HPVersusHeal pawn=" $ string(self) $ " health=" $ string(NewHealth));
    return True;
}

function ApplyVersusSpellLock(float Duration)
{
    if (Role != ROLE_Authority || Duration <= 0.0 || bVersusDead)
        return;
    VersusSpellLockEndTime = FMax(
        VersusSpellLockEndTime,
        Level.TimeSeconds + Duration);
    Log("HPVersusSpellLock pawn=" $ string(self)
        $ " end=" $ string(VersusSpellLockEndTime));
}

function ApplyVersusDisarm(float Duration)
{
    if (Role != ROLE_Authority || Duration <= 0.0 || bVersusDead)
        return;

    VersusDisarmEndTime = FMax(
        VersusDisarmEndTime,
        Level.TimeSeconds + Duration);
    ApplyVersusSpellLock(Duration);
    ClientVersusDisarmed(VersusDisarmEndTime);
    Log("HPVersusDisarm pawn=" $ string(self)
        $ " end=" $ string(VersusDisarmEndTime));
}

function ClientVersusDisarmed(float ServerEndTime)
{
    local HPVersusWand W;

    VersusDisarmEndTime = FMax(VersusDisarmEndTime, ServerEndTime);
    VersusSpellLockEndTime = FMax(VersusSpellLockEndTime, ServerEndTime);
    W = HPVersusWand(Weapon);
    if (W != None)
        W.StopChargingSpell();
    StopAiming();
}

simulated function bool IsVersusSpellLocked()
{
    return VersusSpellLockEndTime > Level.TimeSeconds;
}

function ApplyVersusSpeedBoost(float Multiplier, float Duration)
{
    if (Role != ROLE_Authority || bVersusDead)
        return;
    Multiplier = FClamp(Multiplier, 1.0, 2.0);
    Duration = FClamp(Duration, 0.1, 30.0);
    VersusSpeedMultiplier = Multiplier;
    VersusSpeedBoostEndTime = Level.TimeSeconds + Duration;
    ApplyVersusSpeedLocally(Multiplier);
    ClientApplyVersusSpeed(Multiplier, VersusSpeedBoostEndTime);
    Log("HPVersusSpeedBoost ON pawn=" $ string(self)
        $ " multiplier=" $ string(Multiplier)
        $ " end=" $ string(VersusSpeedBoostEndTime));
}

simulated function bool IsVersusSpeedBoosted()
{
    if (VersusSpeedBoostEndTime > 0.0
        && VersusSpeedBoostEndTime <= Level.TimeSeconds)
    {
        if (Role == ROLE_Authority)
            ClearVersusSpeedBoost("ExpiredQuery");
        else
        {
            VersusSpeedMultiplier = 1.0;
            VersusSpeedBoostEndTime = 0.0;
            ApplyVersusSpeedLocally(1.0);
        }
        return False;
    }
    return VersusSpeedMultiplier > 1.01
        && VersusSpeedBoostEndTime > Level.TimeSeconds;
}

function ClearVersusSpeedBoost(string Reason)
{
    if (Role != ROLE_Authority)
        return;
    VersusSpeedMultiplier = 1.0;
    VersusSpeedBoostEndTime = 0.0;
    ApplyVersusSpeedLocally(1.0);
    ClientApplyVersusSpeed(1.0, 0.0);
    Log("HPVersusSpeedBoost OFF pawn=" $ string(self) $ " reason=" $ Reason);
}

simulated function ApplyVersusSpeedLocally(float Multiplier)
{
    if (Multiplier > 1.01)
    {
        if (!bVersusSpeedBaseCaptured)
        {
            VersusSavedGroundSpeed = GroundSpeed;
            VersusSavedGroundRunSpeed = GroundRunSpeed;
            VersusSavedDirectMoveSpeed = VersusDirectMoveSpeed;
            bVersusSpeedBaseCaptured = True;
        }
        GroundSpeed = VersusSavedGroundSpeed * Multiplier;
        GroundRunSpeed = VersusSavedGroundRunSpeed * Multiplier;
        VersusDirectMoveSpeed = VersusSavedDirectMoveSpeed * Multiplier;
    }
    else if (bVersusSpeedBaseCaptured)
    {
        GroundSpeed = VersusSavedGroundSpeed;
        GroundRunSpeed = VersusSavedGroundRunSpeed;
        VersusDirectMoveSpeed = VersusSavedDirectMoveSpeed;
        bVersusSpeedBaseCaptured = False;
    }
}

function ClientApplyVersusSpeed(float Multiplier, float EndTime)
{
    VersusSpeedMultiplier = Multiplier;
    VersusSpeedBoostEndTime = EndTime;
    ApplyVersusSpeedLocally(Multiplier);
}

simulated function BeginVersusSpongify(HPVersusSpongifyPad Pad,
    vector LaunchVelocity, vector TargetLocation)
{
    if (Role != ROLE_Authority || bVersusDead || Pad == None
        || !Pad.IsEnabled())
        return;

    bVersusSpongifyActive = True;
    VersusSpongifyTargetLocation = TargetLocation;
    HitSpongifyPad = None;
    AnimFalling = SpongifyFallAnim;
    fHighestZ = Location.Z;
    SetPhysics(PHYS_Falling);
    Acceleration = vect(0.00,0.00,0.00);
    Velocity = LaunchVelocity;
    ClientBeginVersusSpongify(LaunchVelocity, TargetLocation);
    Log("HPVersusSpongify begin pawn=" $ string(self)
        $ " pad=" $ string(Pad)
        $ " velocity=" $ string(LaunchVelocity)
        $ " target=" $ string(TargetLocation));
}

function ClientBeginVersusSpongify(vector LaunchVelocity,
    vector TargetLocation)
{
    bVersusSpongifyActive = True;
    VersusSpongifyTargetLocation = TargetLocation;
    HitSpongifyPad = None;
    AnimFalling = SpongifyFallAnim;
    SetPhysics(PHYS_Falling);
    Acceleration = vect(0.00,0.00,0.00);
    Velocity = LaunchVelocity;
    PlayInAir();
}

function ClearVersusSpongify(string Reason)
{
    local bool bWasActive;

    bWasActive = bVersusSpongifyActive;
    bVersusSpongifyActive = False;
    VersusSpongifyTargetLocation = vect(0.00,0.00,0.00);
    HitSpongifyPad = None;
    if (AnimFalling == SpongifyFallAnim)
        AnimFalling = HarryAnims[HarryAnimSet].fall;
    if (Role == ROLE_Authority && bWasActive)
        ClientClearVersusSpongify();
    if (bWasActive)
        Log("HPVersusSpongify end pawn=" $ string(self)
            $ " reason=" $ Reason
            $ " location=" $ string(Location));
}

function ClientClearVersusSpongify()
{
    bVersusSpongifyActive = False;
    VersusSpongifyTargetLocation = vect(0.00,0.00,0.00);
    HitSpongifyPad = None;
    if (AnimFalling == SpongifyFallAnim)
        AnimFalling = HarryAnims[HarryAnimSet].fall;
}

function ResetVersusCombatEffects()
{
    ClearVersusSpongify("CombatReset");
    VersusCooldownEndTime = 0.0;
    VersusSpellLockEndTime = 0.0;
    VersusDisarmEndTime = 0.0;
    VersusSpeedMultiplier = 1.0;
    VersusSpeedBoostEndTime = 0.0;
    NextVersusClientCastTime = 0.0;
    NextVersusServerCastTime = 0.0;
    ApplyVersusSpeedLocally(1.0);
    if (Role == ROLE_Authority)
        ClientResetVersusCombatEffects();
}

function ClientResetVersusCombatEffects()
{
    ClientClearVersusSpongify();
    VersusCooldownEndTime = 0.0;
    VersusSpellLockEndTime = 0.0;
    VersusDisarmEndTime = 0.0;
    VersusSpeedMultiplier = 1.0;
    VersusSpeedBoostEndTime = 0.0;
    NextVersusClientCastTime = 0.0;
    NextVersusServerCastTime = 0.0;
    ApplyVersusSpeedLocally(1.0);
}

function ApplyVersusImpulse(Vector Impulse)
{
    if (Role != ROLE_Authority || bVersusDead)
        return;
    Velocity += Impulse;
    SetPhysics(PHYS_Falling);
    ClientVersusImpulse(Impulse);
    Log("HPVersusImpulse pawn=" $ string(self) $ " impulse=" $ string(Impulse));
}

function ClientVersusImpulse(Vector Impulse)
{
    Velocity += Impulse;
    SetPhysics(PHYS_Falling);
}

state VersusDead
{
    ignores Fire, AltFire, DoJump, TakeDamage;

    function BeginState()
    {
        ClearVersusInput();
        bKeepStationary = True;
        bFrozen = True;
        Velocity = vect(0,0,0);
        Acceleration = vect(0,0,0);
        SetPhysics(PHYS_None);
        PlayAnim('faint', 1.0, 0.2);
    }
}

function PlayJumpEmoteSound()
{
    // Reuse short neutral exertion sounds already shipped in HPSounds, with a
    // small pitch split so the three playable characters remain distinct.
    if (Mesh == SkeletalMesh'HPModels.skronPlayerMesh')
    {
        PlayOwnedSound(Sound'HPSounds.Har_Emotes.jump1', SLOT_Talk, 1.35, False, 1200.0, 0.88);
        return;
    }

    if (Mesh == SkeletalMesh'HPModels.skhermionePlayerMesh')
    {
        PlayOwnedSound(Sound'HPSounds.Har_Emotes.jump2', SLOT_Talk, 1.25, False, 1200.0, 1.12);
        return;
    }

    Super.PlayJumpEmoteSound();
}

// Harry's idle_1/fidget variants contain bones that are not safe on every
// linked cosmetic skeleton. The common Idle sequence is present in the
// accepted player set and keeps new roster characters out of reference pose.
function bool UsesStableVersusIdle()
{
    return class'HPVersusCharacterProfiles'.static.ShouldLinkHarryAnimations(Mesh);
}

function name GetCurrIdleAnimName()
{
    if (UsesStableVersusIdle())
        return HarryAnims[HarryAnimSet].Idle;

    return Super.GetCurrIdleAnimName();
}

function name GetCurrFidgetAnimName()
{
    if (UsesStableVersusIdle())
        return HarryAnims[HarryAnimSet].Idle;

    return Super.GetCurrFidgetAnimName();
}

function ApplyCharacterSkin(string CharacterName)
{
    local Texture ProfileSkin;

    CharacterName = class'HPVersusCharacterProfiles'.static.ValidateProfileId(
        CharacterName);

    // Presentation changes never modify the accepted gameplay cylinder.
    SetCollisionSize(Default.CollisionRadius, Default.CollisionHeight);
    Mesh = class'HPVersusCharacterProfiles'.static.GetMesh(CharacterName);
    DrawScale = class'HPVersusCharacterProfiles'.static.GetDrawScale(
        CharacterName);
    PrePivot = Default.PrePivot;
    PrePivot.Z += class'HPVersusCharacterProfiles'.static.GetVisualOffsetZ(
        CharacterName);
    bAlignBottom = True;
    bAlignBottomAlways = True;

    MultiSkins[0] = Default.MultiSkins[0];
    MultiSkins[1] = Default.MultiSkins[1];
    ProfileSkin = class'HPVersusCharacterProfiles'.static.GetSkin(
        CharacterName, 0);
    if (ProfileSkin != None)
        MultiSkins[0] = ProfileSkin;
    ProfileSkin = class'HPVersusCharacterProfiles'.static.GetSkin(
        CharacterName, 1);
    if (ProfileSkin != None)
        MultiSkins[1] = ProfileSkin;

    if (class'HPVersusCharacterProfiles'.static.IsTranslucent(CharacterName))
        Style = STY_Translucent;
    else
        Style = STY_Normal;
    Opacity = class'HPVersusCharacterProfiles'.static.GetOpacity(CharacterName);

    EnsureVersusPlayerAnimationSet();
    if (UsesStableVersusIdle() && Physics != PHYS_Falling
        && VSize2D(Velocity) < 5.0)
    {
        CurrIdleAnimName = HarryAnims[HarryAnimSet].Idle;
        LoopAnim(CurrIdleAnimName, 0.8, 0.15,, HarryAnimType);
    }
    if (class'HPVersusCharacterProfiles'.static.GetCloakStrategy(Mesh) != 0)
    {
        EnsureVersusCloakAnimationChannels();
        UpdateVersusCloakAnimation();
    }

    Log("HPVersusCharacterSkin pawn=" $ string(self)
        $ " character=" $ CharacterName
        $ " status="
        $ class'HPVersusCharacterProfiles'.static.GetAuditStatus(CharacterName)
        $ " mesh=" $ string(Mesh)
        $ " animSet=" $ string(SkelAnim)
        $ " collision=" $ string(CollisionRadius)
        $ "x" $ string(CollisionHeight)
        $ " wandBone="
        $ string(class'HPVersusCharacterProfiles'.static.GetWandBone(CharacterName))
        $ " wandBoneIndex="
        $ string(BoneNumber(
            class'HPVersusCharacterProfiles'.static.GetWandBone(CharacterName)))
        $ " hasIdle=" $ string(HasAnim(HarryAnims[0].Idle))
        $ " hasRun=" $ string(HasAnim(HarryAnims[0].run))
        $ " hasRunback=" $ string(HasAnim(HarryAnims[0].WalkBack))
        $ " hasStrafeL=" $ string(HasAnim(HarryAnims[0].StrafeLeft))
        $ " hasStrafeR=" $ string(HasAnim(HarryAnims[0].StrafeRight))
