//-----------------------------------------------------------------------------
// v11 spell flow.
//
// HP2's real LMB path is AltFire -> StartAiming -> cHarryAnimChannel -> Cast.
// Fire is not the animation callback, so overriding Fire alone never reached
// the server for the normal binding.  Keep the original aim/charge/cast
// animation and replace only the final Cast action with an authoritative RPC.
//-----------------------------------------------------------------------------

exec function AltFire(optional float f)
{
    if (!bIsAiming && Weapon != None)
    {
        VersusAimStartTime = Level.TimeSeconds;
        Log("HPVersusAimStart pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " weapon=" $ string(Weapon)
            $ " cursor=" $ string(SpellCursor));
        LogVersusSpellState("AimStart");
    }

    Super.AltFire(f);
}

function StopAiming()
{
    // cHarryAnimChannel.stateIdle calls PlayIdle immediately on state entry.
    // Select full-body replacement before that callback so the cast layer
    // releases the wand arm even while the player remains stationary.
    if (CarryingActor == None)
    {
        HarryAnimType = AT_Replace;
        if (HarryAnimChannel != None)
            HarryAnimChannel.GotoState('stateIdle');
        TurnOffCastingVars();
        TurnOffSpellCursor();
        if (bHarryUsingSword)
            StopSound(Sound'sword_buildup', SLOT_Interact);
    }
}

function TurnOffSpellCursor()
{
    local baseWand W;

    bIsAimingWithCharge = False;
    W = baseWand(Weapon);
    if (W != None)
        W.StopChargingSpell();

    if (SpellCursor != None)
        SpellCursor.TurnTargetingOff();

    GroundSpeed = GroundRunSpeed;
}

function rotator GetVersusAimRotation()
{
    local rotator AimRot;

    if (IsVersusFreeLookDetached())
        AimRot = VersusFreeLookAimRotation;
    else if (IsLocalViewportPlayer() && Cam != None)
        AimRot = Cam.Rotation;
    else
        AimRot = ViewRotation;

    AimRot.Roll = 0;
    return AimRot;
}

function vector GetVersusFallbackMuzzle(rotator AimRot)
{
    local rotator FlatRot;
    local vector Start;

    FlatRot = AimRot;
    FlatRot.Pitch = 0;
    FlatRot.Roll = 0;

    Start = Location
        + vector(FlatRot) * (CollisionRadius + VersusMuzzleForwardOffset);
    Start.Z += VersusMuzzleHeightOffset * DrawScale;
    return Start;
}

function vector GetVersusClientMuzzle(rotator AimRot)
{
    local vector Candidate;

    // Preserve the original HP2 wand-bone muzzle when the local skeletal pose
    // has supplied a plausible world transform.  Network/dedicated pawns can
    // leave WeaponLoc at zero or at an old map position, so keep a fallback.
    if (WeaponLoc != vect(0.00,0.00,0.00)
        && VSize(WeaponLoc - Location) <= VersusMuzzleMaxDistance)
    {
        Candidate = WeaponLoc
            - (vect(0.00,0.00,20.00) >> WeaponRot);

        if (VSize(Candidate - Location) <= VersusMuzzleMaxDistance)
            return Candidate;
    }

    return GetVersusFallbackMuzzle(AimRot);
}

function int NormalizeVersusRotationAxis(int Axis)
{
    Axis = Axis & 65535;
    if (Axis > 32767)
        Axis -= 65536;

    return Axis;
}

function rotator ValidateVersusAim(rotator AimRot)
{
    AimRot.Pitch = NormalizeVersusRotationAxis(AimRot.Pitch);
    AimRot.Yaw = NormalizeVersusRotationAxis(AimRot.Yaw);
    AimRot.Roll = 0;

    // Enough vertical freedom for arena stairs/jumps, without accepting an
    // upside-down client view as authoritative projectile input.
    if (AimRot.Pitch > 15000)
        AimRot.Pitch = 15000;
    else if (AimRot.Pitch < -15000)
        AimRot.Pitch = -15000;

    return AimRot;
}

function RequestVersusCast(float Charge)
{
    local rotator AimRot;
    local vector ClientMuzzle;
    local HPVersusWand W;

    if (bVersusDead || Health <= 0)
        return;

    W = HPVersusWand(Weapon);
    if (W == None)
    {
        Log("HPVersusCastRequest REJECT no versus wand pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " weapon=" $ string(Weapon));
        return;
    }

    if (Level.TimeSeconds < NextVersusClientCastTime || IsVersusSpellLocked())
        return;

    NextVersusClientCastTime = Level.TimeSeconds
        + GetVersusSpellCooldown(SelectedVersusSpell);
    AimRot = GetVersusAimRotation();
    ClientMuzzle = GetVersusClientMuzzle(AimRot);
    Charge = FClamp(Charge, 0.0, 1.0);

    Log("HPVersusCastRequest pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " Role=" $ string(Role)
        $ " weapon=" $ string(W)
        $ " wandOwner=" $ string(W.Owner)
        $ " selectedSlot=" $ string(SelectedVersusSpell)
        $ " charge=" $ string(Charge)
        $ " aim=" $ string(AimRot)
        $ " pawnLoc=" $ string(Location)
        $ " weaponLoc=" $ string(WeaponLoc)
        $ " muzzle=" $ string(ClientMuzzle));

    ServerRequestCast(Charge, AimRot, ClientMuzzle);
}

function Cast()
{
    local float Charge;
    local HPVersusWand W;

    W = HPVersusWand(Weapon);
    if (W != None)
        Charge = W.ChargingLevel();

    // The owning network copy can receive the wand after aiming has begun.
    // Keep a pawn-local timer as a deterministic charge fallback.
    if (Charge <= 0.0 && VersusAimStartTime >= 0.0)
    {
        if (VersusChargeDuration > 0.0)
            Charge = (Level.TimeSeconds - VersusAimStartTime)
                / VersusChargeDuration;
        else
            Charge = 1.0;
    }

    RequestVersusCast(Charge);
    VersusAimStartTime = -1.0;
    TurnOffSpellCursor();
}

function Fire(optional float f)
{
    // Retain an immediate console/binding fallback without entering the base
    // bJustFired resolver. The normal LeftMouse path uses Cast() above.
    if (Weapon != None)
    {
        Weapon.bPointing = True;
        RequestVersusCast(1.0);
    }
}

function ServerSelectVersusSpell(byte NewSpellSlot)
{
    local HPVersusWand W;
    local Class<baseSpell> SpellClass;

    if (Role != ROLE_Authority)
        return;

    SpellClass = GetVersusSpellClass(NewSpellSlot);
    if (SpellClass == None)
    {
        Log("HPVersusSpellSelect REJECT pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " requested=" $ string(NewSpellSlot));
        return;
    }

    SelectedVersusSpell = NewSpellSlot;
    W = EnsureServerVersusWand();
    ApplyVersusSpellSelection(W);

    Log("HPVersusSpellSelect pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " selected=" $ string(SelectedVersusSpell)
        $ " class=" $ string(SpellClass)
        $ " wand=" $ string(W));
}

exec function VersusSelectSpell(byte NewSpellSlot)
{
    local HPVersusWand W;

    // Immediate owner-local UI/charge preview. The server still maps the
    // byte through GetVersusSpellClass and the wand repeats its class
    // whitelist before an authoritative projectile can exist.
    if (NewSpellSlot > 5)
    {
        ClientMessage("Unknown Versus spell slot: " $ string(NewSpellSlot));
        return;
    }

    SelectedVersusSpell = NewSpellSlot;
    W = HPVersusWand(Weapon);
    if (W != None)
        W.ApplyVersusVisualSpell(NewSpellSlot);

    ServerSelectVersusSpell(NewSpellSlot);
    ClientMessage("Selected spell: " $ GetVersusSpellName(NewSpellSlot));
}

