function ServerRequestCast(float Charge, Rotator AimRot, Vector ClientMuzzle)
{
    local HPVersusWand W;
    local Class<baseSpell> SpellClass;
    local baseSpell SpawnedSpell;
    local vector ServerMuzzle;
    local float MuzzleDelta;
    local bool bUsedClientMuzzle;

    if (Role != ROLE_Authority)
        return;

    if (Level.TimeSeconds < NextVersusServerCastTime)
    {
        Log("HPVersusCastReject reason=cooldown pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot));
        return;
    }

    if (bVersusDead || Health <= 0)
    {
        Log("HPVersusCastReject reason=dead pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot));
        return;
    }

    if (VersusSpellLockEndTime > Level.TimeSeconds)
    {
        Log("HPVersusCastReject reason=spell-lock pawn=" $ string(self)
            $ " until=" $ string(VersusSpellLockEndTime));
        return;
    }

    W = HPVersusWand(Weapon);
    if (W == None || W.Owner != self)
        W = EnsureServerVersusWand();

    if (W == None || Weapon != W || W.Owner != self)
    {
        Log("HPVersusCastReject reason=wand pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " weapon=" $ string(Weapon)
            $ " wand=" $ string(W));
        return;
    }

    SpellClass = GetVersusSpellClass(SelectedVersusSpell);
    if (SpellClass == None)
    {
        Log("HPVersusCastReject reason=spell-slot pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " selected=" $ string(SelectedVersusSpell));
        return;
    }

    NextVersusServerCastTime = Level.TimeSeconds
        + GetVersusSpellCooldown(SelectedVersusSpell);
    VersusCooldownEndTime = NextVersusServerCastTime;
    Charge = FClamp(Charge, 0.0, 1.0);
    AimRot = ValidateVersusAim(AimRot);
    ServerMuzzle = GetVersusFallbackMuzzle(AimRot);
    MuzzleDelta = VSize(ClientMuzzle - Location);

    // The position is accepted only as a tightly bounded wand-bone candidate.
    // Server pawn Location remains the trust anchor and supplies the fallback.
    if (ClientMuzzle != vect(0.00,0.00,0.00)
        && MuzzleDelta <= VersusMuzzleMaxDistance)
    {
        ServerMuzzle = ClientMuzzle;
        bUsedClientMuzzle = True;
    }

    W.BindVersusOwner();
    ApplyVersusSpellSelection(W);
    SpawnedSpell = W.CastVersusSpell(
        self,
        ServerMuzzle,
        AimRot,
        Charge,
        SpellClass);

    // A locally valid hand point can still overlap server geometry after a
    // correction. Retry once from the deterministic pawn-relative muzzle.
    if (SpawnedSpell == None && bUsedClientMuzzle)
    {
        ServerMuzzle = GetVersusFallbackMuzzle(AimRot);
        bUsedClientMuzzle = False;
        SpawnedSpell = W.CastVersusSpell(
            self,
            ServerMuzzle,
            AimRot,
            Charge,
            SpellClass);
    }

    // The stock cast pose lives only in the owning client's non-replicated
    // cHarryAnimChannel. Publish a compact presentation event only after an
    // authoritative projectile really exists.
    if (SpawnedSpell != None)
    {
        // Keep the replicated event counter deterministic in the old byte
        // implementation during long stress-fire sessions.
        if (VersusCastSerial == 255)
            VersusCastSerial = 0;
        else
            VersusCastSerial++;
    }

    Log("HPVersusServerCast pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " weapon=" $ string(W)
        $ " owner=" $ string(W.Owner)
        $ " selectedSlot=" $ string(SelectedVersusSpell)
        $ " spellClass=" $ string(SpellClass)
        $ " charge=" $ string(Charge)
        $ " aim=" $ string(AimRot)
        $ " clientMuzzle=" $ string(ClientMuzzle)
        $ " muzzleDelta=" $ string(MuzzleDelta)
        $ " usedClientMuzzle=" $ string(bUsedClientMuzzle)
        $ " serverMuzzle=" $ string(ServerMuzzle)
        $ " castSerial=" $ string(VersusCastSerial)
        $ " spawned=" $ string(SpawnedSpell));
}

