//=============================================================================
// HPVersusHarry.
//
// Player pawn for the experimental 1v1 mode. It inherits the HP2 movement,
// camera, wand and animation logic from harry, but avoids the coop prototype's
// forced immortality loop.
//=============================================================================

class HPVersusHarry extends harry;

var bool bVersusDead;
var float LastVersusHitTime;
var float VersusRespawnAt;
var byte VersusRespawnSeconds;
var byte VersusSlot;             // 0..7; assigned by HPVersusGame.Login
var bool bVersusRegistered;      // authoritative slot reservation until Logout

// Experimental direct input bridge for HP2 multiplayer.
// These are bound through User.ini with `Button bVersus...` and are also
// set by HPConsole.KeyEvent as a fallback when normal Axis aliases do not
// reach the network pawn.
var input byte bVersusMoveForward;
var input byte bVersusMoveBack;
var input byte bVersusMoveLeft;
var input byte bVersusMoveRight;
var input byte bVersusJump;
var byte bVersusJumpWasDown;
// Local key state. This is deliberately absent from replication.
var byte bVersusFreeLook;
var bool bVersusFreeLookActive;
var rotator VersusFreeLookPawnRotation;
var rotator VersusFreeLookAimRotation;
var vector VersusFreeLookLastCamLocation;
var float NextVersusFreeLookViewLogTime;
var float NextVersusInputLogTime;
// Set only while an already-running local camera is rebound after the
// warmup countdown. The first live match keeps its current orbit.
var bool bPreserveVersusCameraOnSetup;

// v7: direct server-authoritative movement fallback.  HP2's harry.PlayerWalking
// state was written for single-player and does not call PlayerPawn.ReplicateMove,
// so horizontal axes can reach Acceleration but still never move/replicate on a
// dedicated server.  This bridge moves the pawn explicitly while we keep the
// normal jump path intact.
var float VersusDirectMoveSpeed;
var float VersusDirectAirScale;
var float NextVersusMoveLogTime;

// Local Versus pawns select native PlayerPawn movement on setup; the direct
// movement command remains available as a fallback during field testing.
var bool bUseEngineNetworkMovement;
var bool bVersusMovementChoiceMade;
var float NextVersusNativeTraceTime;
var float NextVersusCorrectionTraceTime;
var float NextVersusAnimTraceTime;
var float NextVersusAnimChannelRetryTime;
var float NextVersusRemoteAnimChannelRetryTime;
var float NextVersusBodyTraceTime;
var float NextVersusProxyTraceTime;
var HPVersusRemoteAnimChannel VersusRemoteAnimChannel;
var HPVersusCloakAnimChannel VersusCloakChannel1;
var HPVersusCloakAnimChannel VersusCloakChannel2;
var name LastVersusCloakAnim;
var bool bLastVersusCloakLoop;
var bool bVersusCloakConfigured;
var bool bVersusCloakFemale;
var bool bVersusCloakProbeLogged;
var byte VersusCastSerial;
var byte LastSeenVersusCastSerial;
var int VersusGroundProbeSerial;

// v11: owner-scoped spell state.  The byte is authoritative and deliberately
// maps through a server whitelist; clients never send a class reference.
var byte SelectedVersusSpell;
var float VersusAimStartTime;
var float NextVersusClientCastTime;
var float NextVersusServerCastTime;
var float VersusCastCooldown;
var float VersusChargeDuration;
var float VersusMuzzleMaxDistance;
var float VersusMuzzleForwardOffset;
var float VersusMuzzleHeightOffset;
var Weapon LastLoggedVersusWeapon;
var SpellCursor LastLoggedVersusCursor;
var float VersusCooldownEndTime;
var float VersusSpellLockEndTime;
var float VersusDisarmEndTime;
var float VersusSpeedMultiplier;
var float VersusSpeedBoostEndTime;
var float VersusSavedGroundSpeed;
var float VersusSavedGroundRunSpeed;
var float VersusSavedDirectMoveSpeed;
var bool bVersusSpeedBaseCaptured;
var bool bVersusSpongifyActive;
var vector VersusSpongifyTargetLocation;
// Minimal shared mode state. Hide & Seek policy remains in HPHideSeekGame.
// 0=None/waiting, 1=Hunter, 2=Hider.
var byte HideSeekRole;
var bool bHideSeekCaught;
var bool bVersusModeMovementLocked;
var bool bVersusModeCastingLocked;
var byte HideSeekDisguiseIndex;
var float NextHideSeekDisguiseTime;

replication
{
    reliable if (Role == ROLE_Authority)
        bVersusDead, VersusSlot, VersusRespawnSeconds, SelectedVersusSpell, VersusCastSerial,
        VersusCooldownEndTime, VersusSpellLockEndTime, VersusDisarmEndTime,
        VersusSpeedMultiplier, VersusSpeedBoostEndTime, ClientSetVersusSlot,
        ClientVersusDeath, ClientVersusRespawn, ClientSyncHealth,
        ClientApplyVersusSpeed, ClientResetVersusCombatEffects,
        ClientVersusImpulse, ClientVersusDisarmed,
        bVersusSpongifyActive, VersusSpongifyTargetLocation,
        ClientBeginVersusSpongify, ClientClearVersusSpongify,
        HideSeekRole, bHideSeekCaught, bVersusModeMovementLocked,
