event PostBeginPlay()
{
    Super.PostBeginPlay();
    // harry.PostBeginPlay() always restores the single-player HPHud.  Select
    // the Versus HUD after the base call so PlayerPawn.PreRender spawns the
    // gameplay overlay for both FFA and Hide & Seek clients.
    HUDType = Class'HPVersusHUD';
    Log("HPVersusBuild version=16 phase=PostBeginPlay pawn=" $ string(self)
        $ " Role=" $ string(Role) $ " NetMode=" $ string(Level.NetMode)
        $ " HUDType=" $ string(HUDType));
    SetupVersusPlayer();
}

simulated event PostNetBeginPlay()
{
    // Do not call the multiplayer workaround appended to harry.uc. Its
    // Role<Authority guard also accepts remote SimulatedProxy pawns and lets
    // them retarget the client's shared BaseCam to themselves. Keep only the
    // original simulated PlayerPawn/Pawn network initialization. Remote proxy
    // pawns stop here; only the autonomous owner/authority may run the versus
    // camera, input and spell bootstrap.
    Super(PlayerPawn).PostNetBeginPlay();
    Log("HPVersusBuild version=16 phase=PostNetBeginPlay pawn=" $ string(self)
        $ " Role=" $ string(Role) $ " NetMode=" $ string(Level.NetMode));

    if (Role < ROLE_AutonomousProxy)
    {
        // HP2 skeletal meshes normally rely on the engine's bottom-alignment
        // pass. A non-owner network Harry is a PHYS_None SimulatedProxy and
        // does not receive the same pawn update path as the locally possessed
        // copy. Force the native "always" variant only on this visual proxy;
        // Location, Physics, collision and the owning player remain untouched.
        bAlignBottom = True;
        bAlignBottomAlways = True;

        Log("HPVersusRemoteBottomAlign phase=PostNetBeginPlay pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " Role=" $ string(Role)
            $ " PrePivot=" $ string(PrePivot)
            $ " SavedPrePivotZ=" $ string(SavedPrePivotZ)
            $ " bAlignBottom=" $ string(bAlignBottom)
            $ " bAlignBottomAlways=" $ string(bAlignBottomAlways));

        // A SimulatedProxy never runs Harry's single-player states or
        // cHarryAnimChannel.  Give it only the visual-only upper-body channel;
        // camera, input, cursor and gameplay bootstrap remain owner-only.
        LastSeenVersusCastSerial = VersusCastSerial;
        EnsureVersusRemoteAnimationChannel("PostNetBeginPlay");
        EnsureVersusPlayerAnimationSet();
        UpdateVersusCloakAnimation();
        return;
    }

    SetupVersusPlayer();
}

event Possess()
{
    Super.Possess();
    SetupVersusPlayer();

    Log("HPVersusHarry: Possess pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " playerObj=" $ string(Player)
        $ " localViewport=" $ string(IsLocalViewportPlayer())
        $ " loc=" $ string(Location));
}

event TravelPostAccept()
{
    // Skip harry.TravelPostAccept(): it is single-player save/SmartStart/status
    // plumbing and can re-open loading/cutscene paths after a network join.
    // PlayerPawn.TravelPostAccept is still needed for the engine-side travel
    // accept path, so call the grandparent explicitly.
    Super(PlayerPawn).TravelPostAccept();
    SetupVersusPlayer();

    Log("HPVersusHarry: TravelPostAccept pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " playerObj=" $ string(Player)
        $ " localViewport=" $ string(IsLocalViewportPlayer())
        $ " loc=" $ string(Location));
}

function ClientSetVersusSlot(byte NewSlot)
{
    VersusSlot = NewSlot;
    Log("HPVersusHarry: ClientSetVersusSlot pawn=" $ string(self) $ " slot=" $ string(VersusSlot));
}

simulated function string GetHideSeekRoleName()
{
    if (bHideSeekCaught)
        return "CAUGHT";
    if (HideSeekRole == 1)
        return "HUNTER";
    if (HideSeekRole == 2)
        return "HIDER";
    return "WAITING";
}

simulated function string GetHideSeekDisguiseName()
{
    return class'HPHideSeekDisguiseCatalog'.static.GetDisplayName(
        HideSeekDisguiseIndex);
}

simulated function bool IsHideSeekDisguised()
{
    return HideSeekDisguiseIndex != 0;
}

function PrepareHideSeekRound()
{
    if (Role != ROLE_Authority)
        return;
    ResetVersusCombatEffects();
    ClearHideSeekDisguise();
    bVersusDead = False;
    VersusRespawnAt = 0.0;
    VersusRespawnSeconds = 0;
    Health = 100;
    SetHealth(100);
    ClientSyncHealth(100);
    bHidden = False;
    DrawType = DT_Mesh;
    SetCollision(True, True, True);
    bCollideWorld = True;
    bProjTarget = True;
    bFrozen = False;
    bKeepStationary = False;
    if (!IsInState('PlayerWalking'))
        GotoState('PlayerWalking');
    SetPhysics(PHYS_Walking);
}

function SetHideSeekModeState(byte NewRole, bool bCaught,
    bool bMovementLocked, bool bCastingLocked)
{
    if (Role != ROLE_Authority)
        return;
    HideSeekRole = NewRole;
    bHideSeekCaught = bCaught;
    bVersusModeMovementLocked = bMovementLocked;
    bVersusModeCastingLocked = bCastingLocked;
    ApplyHideSeekModePresentation();
    ClientApplyHideSeekModeState(NewRole, bCaught,
        bMovementLocked, bCastingLocked, HideSeekDisguiseIndex);
    BroadcastHideSeekVisual();
}

simulated function ResetHideSeekLockedAnimation()
{
    // A pawn can enter the hide-phase lock while the native movement channel
    // still contains Fall. PHYS_None then freezes that pose indefinitely.
    // Put the accepted player skeleton back into its normal idle channel at
    // the same moment movement is frozen. Disguise meshes stay static.
    if (IsHideSeekDisguised())
        return;

    HarryAnimType = AT_Replace;
    if (HarryAnimChannel != None)
        HarryAnimChannel.GotoState('stateIdle');
    PlayIdle();
}

simulated function ApplyHideSeekModePresentation()
{
    if (bHideSeekCaught)
    {
        bHidden = True;
        DrawType = DT_None;
        SetCollision(False, False, False);
        bCollideWorld = False;
        bProjTarget = False;
        Velocity = vect(0,0,0);
        Acceleration = vect(0,0,0);
        SetPhysics(PHYS_None);
        ResetHideSeekLockedAnimation();
        return;
    }

    bHidden = False;
    DrawType = DT_Mesh;
    SetCollision(True, True, True);
    bCollideWorld = True;
    bProjTarget = True;
    if (bVersusModeMovementLocked)
    {
        Velocity = vect(0,0,0);
        Acceleration = vect(0,0,0);
        SetPhysics(PHYS_None);
        ResetHideSeekLockedAnimation();
    }
    else if (Physics == PHYS_None || Physics == PHYS_Rotating)
        SetPhysics(PHYS_Walking);
}

function ClientApplyHideSeekModeState(byte NewRole, bool bCaught,
    bool bMovementLocked, bool bCastingLocked, byte NewDisguise)
{
    HideSeekRole = NewRole;
    bHideSeekCaught = bCaught;
    bVersusModeMovementLocked = bMovementLocked;
    bVersusModeCastingLocked = bCastingLocked;
    HideSeekDisguiseIndex = NewDisguise;
    ApplyHideSeekModePresentation();
    ClientObserveHideSeekVisual(self, NewDisguise, bCaught);
}

function BroadcastHideSeekVisual()
{
    local HPVersusHarry Observer;

    if (Role != ROLE_Authority)
        return;
    foreach AllActors(Class'HPVersusHarry', Observer)
        if (Observer.Player != None)
            Observer.ClientObserveHideSeekVisual(
                self, HideSeekDisguiseIndex, bHideSeekCaught);
}

function ClientObserveHideSeekVisual(HPVersusHarry Target,
    byte NewDisguise, bool bCaught)
{
    local HPVersusPRI VPRI;
    local Mesh ProfileMesh;

    if (Target == None)
        return;
    Target.HideSeekDisguiseIndex = NewDisguise;
    Target.bHideSeekCaught = bCaught;
    if (bCaught)
    {
        Target.bHidden = True;
        Target.DrawType = DT_None;
        Target.SetCollision(False, False, False);
        Target.bCollideWorld = False;
        return;
    }

    Target.bHidden = False;
    Target.DrawType = DT_Mesh;
    if (NewDisguise == 0)
    {
        VPRI = HPVersusPRI(Target.PlayerReplicationInfo);
        if (VPRI != None)
            Target.ApplyCharacterSkin(VPRI.SelectedCharacter);
        return;
    }

    ProfileMesh = class'HPHideSeekDisguiseCatalog'.static.GetMesh(
        NewDisguise);
    if (ProfileMesh == None)
        return;
    Target.Mesh = ProfileMesh;
    Target.DrawScale = class'HPHideSeekDisguiseCatalog'.static.GetDrawScale(
        NewDisguise);
    Target.Style = STY_Normal;
    Target.Opacity = 1.0;
    Target.PrePivot = vect(0,0,0);
    Target.bAlignBottom = False;
    Target.bAlignBottomAlways = False;
    Target.AnimRate = 0.0;
    Target.AnimFrame = 0.0;
    Target.bAnimLoop = False;
}

function ApplyHideSeekDisguise(byte NewDisguise)
{
    local HPVersusPRI VPRI;
    local Mesh ProfileMesh;

    if (Role != ROLE_Authority
        || !class'HPHideSeekDisguiseCatalog'.static.IsValid(NewDisguise))
        return;
    HideSeekDisguiseIndex = NewDisguise;
    if (NewDisguise == 0)
    {
        VPRI = HPVersusPRI(PlayerReplicationInfo);
        if (VPRI != None)
            ApplyCharacterSkin(VPRI.SelectedCharacter);
    }
    else
    {
        ProfileMesh = class'HPHideSeekDisguiseCatalog'.static.GetMesh(
            NewDisguise);
        if (ProfileMesh == None)
            return;
        Mesh = ProfileMesh;
        DrawScale = class'HPHideSeekDisguiseCatalog'.static.GetDrawScale(
            NewDisguise);
        MultiSkins[0] = None;
        MultiSkins[1] = None;
        Style = STY_Normal;
        Opacity = 1.0;
        PrePivot = vect(0,0,0);
        bAlignBottom = False;
        bAlignBottomAlways = False;
        AnimRate = 0.0;
        AnimFrame = 0.0;
        bAnimLoop = False;
        // Disguise is presentation only; never copy prop collision.
        SetCollisionSize(Default.CollisionRadius, Default.CollisionHeight);
    }
    BroadcastHideSeekVisual();
}

function ClearHideSeekDisguise()
{
    if (Role == ROLE_Authority)
        ApplyHideSeekDisguise(0);
}

exec function CycleVersusDisguise()
{
    ServerCycleHideSeekDisguise();
}

function ServerCycleHideSeekDisguise()
{
    local HPVersusGame G;
    local byte NextProfile;

    if (Role != ROLE_Authority || Level.TimeSeconds < NextHideSeekDisguiseTime)
        return;
    G = HPVersusGame(Level.Game);
    if (G == None || !G.CanVersusDisguise(self))
        return;
    NextHideSeekDisguiseTime = Level.TimeSeconds + 0.25;
    NextProfile = HideSeekDisguiseIndex + 1;
    if (!class'HPHideSeekDisguiseCatalog'.static.IsValid(NextProfile))
        NextProfile = 0;
    ApplyHideSeekDisguise(NextProfile);
    ClientMessage("Disguise: "
        $ class'HPHideSeekDisguiseCatalog'.static.GetDisplayName(NextProfile));
}

function bool IsLocalViewportPlayer()
{
    return Player != None && Viewport(Player) != None;
}

function bool UseEngineNetworkMovement()
{
    return bUseEngineNetworkMovement;
}

function bool UseNetworkMovementAnimation()
{
    return bUseEngineNetworkMovement;
}

function bool HandleNetworkMovementAnimEnd()
{
    // A looping locomotion sequence also raises AnimEnd. At a direction
    // reversal the stock speed-only decision can insert Idle before the next
    // ProcessMove. Leave landing, waiting/fidgets and airborne states stock.
    if (!bUseEngineNetworkMovement || !IsVersusMovementAnim(AnimSequence))
        return False;

    ReconcileVersusMovementAnimation("MovementAnimEnd");
    return True;
}

function bool EnsureVersusAnimationChannel(string Phase)
{
    if (HarryAnimChannel != None)
        return True;

    // harry.PostBeginPlay creates this non-replicated helper on the machine
    // where the pawn originates.  A pawn spawned by the dedicated server can
    // therefore reach its owning client without a local cHarryAnimChannel.
    // Jump/Fall still work because they call PlayAnim on Harry directly, while
    // TweenToRunning/TweenToWaiting require this channel and silently abort.
    if (!IsLocalViewportPlayer())
        return False;

    if (Mesh == None)
        return False;

    if (Level.TimeSeconds < NextVersusAnimChannelRetryTime)
        return False;

    NextVersusAnimChannelRetryTime = Level.TimeSeconds + 1.0;

    HarryAnimChannel = cHarryAnimChannel(CreateAnimChannel(Class'HPVersusAnimChannel', AT_Replace, 'bip01 spine1'));

    if (HarryAnimChannel == None)
    {
        Log("HPVersusAnimChannel FAILED phase=" $ Phase
            $ " pawn=" $ string(self)
            $ " mesh=" $ string(Mesh)
            $ " role=" $ string(Role));
        return False;
    }

    HarryAnimChannel.SetOwner(self);
    HarryAnimType = AT_Replace;
    bAnimTransition = False;

    Log("HPVersusAnimChannel CREATED phase=" $ Phase
        $ " pawn=" $ string(self)
        $ " channel=" $ string(HarryAnimChannel)
        $ " state=" $ string(HarryAnimChannel.GetStateName())
        $ " mesh=" $ string(Mesh)
        $ " role=" $ string(Role));
    return True;
}

simulated function bool EnsureVersusRemoteAnimationChannel(string Phase)
{
    if (Role != ROLE_SimulatedProxy)
        return False;

    if (VersusRemoteAnimChannel != None)
        return True;

    if (Mesh == None)
        return False;

    if (Level.TimeSeconds < NextVersusRemoteAnimChannelRetryTime)
        return False;

    NextVersusRemoteAnimChannelRetryTime = Level.TimeSeconds + 0.10;
    VersusRemoteAnimChannel = HPVersusRemoteAnimChannel(CreateAnimChannel(
        Class'HPVersusRemoteAnimChannel',
        AT_Replace,
        'bip01 spine1'));

    if (VersusRemoteAnimChannel == None)
    {
        Log("HPVersusRemoteAnimChannel FAILED phase=" $ Phase
            $ " pawn=" $ string(self)
            $ " mesh=" $ string(Mesh)
            $ " Role=" $ string(Role));
        return False;
    }

    VersusRemoteAnimChannel.SetOwner(self);
    Log("HPVersusRemoteAnimChannel CREATED phase=" $ Phase
        $ " pawn=" $ string(self)
        $ " channel=" $ string(VersusRemoteAnimChannel)
        $ " mesh=" $ string(Mesh)
        $ " Role=" $ string(Role));
    return True;
}

simulated function bool PlayVersusRemoteCast()
{
    if (!EnsureVersusRemoteAnimationChannel("RemoteCast"))
        return False;

    VersusRemoteAnimChannel.PlayRemoteCast();
    Log("HPVersusRemoteCast pawn=" $ string(self)
        $ " channel=" $ string(VersusRemoteAnimChannel)
        $ " Location=" $ string(Location)
        $ " AnimSequence=" $ string(AnimSequence));
    return True;
}

simulated function RestoreVersusRemoteBaseAnimation()
{
    local name SavedSequence;
    local float SavedFrame;
    local float SavedRate;
    local float SavedTweenRate;
    local float SavedLast;
    local float SavedMinRate;
    local float SavedOldRate;
    local plane SavedSimAnim;
    local bool bSavedLoop;
    local bool bSavedFinished;
    local bool bSavedNotify;

    if (Role != ROLE_SimulatedProxy || VersusRemoteAnimChannel == None)
        return;

    if (!VersusRemoteAnimChannel.IsInState('stateRelease'))
        return;

    // Wait for the existing base tween to finish: its private native blend
    // buffer cannot be reconstructed from the exposed animation fields.
    if (AnimSequence == 'None' || AnimFrame < 0.0)
        return;

    SavedSequence = AnimSequence;
    SavedFrame = AnimFrame;
    SavedRate = AnimRate;
    SavedTweenRate = TweenRate;
    SavedLast = AnimLast;
    SavedMinRate = AnimMinRate;
    SavedOldRate = OldAnimRate;
    SavedSimAnim = SimAnim;
    bSavedLoop = bAnimLoop;
    bSavedFinished = bAnimFinished;
    bSavedNotify = bAnimNotify;

    // Stock cHarryAnimChannel returns control through an AT_Replace base
    // animation. Do the same using the currently replicated sequence rather
    // than PlayIdle/StopAiming, which would run remote gameplay/idle logic.
    // Preserve the received locomotion phase and loop flags. Verify the
    // secondary-channel release visually on the installed M212 build.
    PlayAnim(SavedSequence, 1.0, 0.0, AT_Replace);
    AnimFrame = SavedFrame;
    AnimRate = SavedRate;
    TweenRate = SavedTweenRate;
    AnimLast = SavedLast;
    AnimMinRate = SavedMinRate;
    OldAnimRate = SavedOldRate;
    SimAnim = SavedSimAnim;
    bAnimLoop = bSavedLoop;
    bAnimFinished = bSavedFinished;
    bAnimNotify = bSavedNotify;
    VersusRemoteAnimChannel.GotoState('stateIdle');

    Log("HPVersusRemoteCast RELEASE pawn=" $ string(self)
        $ " sequence=" $ string(AnimSequence)
        $ " frame=" $ string(AnimFrame)
        $ " rate=" $ string(AnimRate));
}

