function ServerVersusNetState(string ClientPhase)
{
    local HPVersusHarry H;

    if (Role != ROLE_Authority)
        return;

    LogVersusNetState("ServerFor_" $ ClientPhase);

    // Reuse the existing diagnostic RPC, not a second movement protocol.
    // A request id lets the client and server snapshots be paired by slot
    // even though their Level.TimeSeconds have different origins.
    if (Left(ClientPhase, 12) == "GroundProbe_")
    {
        foreach AllActors(Class'HPVersusHarry', H)
            H.LogVersusGroundState(ClientPhase);
    }
}

simulated function LogVersusGroundState(string Phase)
{
    local Actor FloorActor;
    local vector FloorLocation;
    local vector FloorNormal;
    local vector LeftFoot;
    local vector RightFoot;
    local bool bLocalViewport;

    bLocalViewport = Player != None && Viewport(Player) != None;
    FloorActor = Trace(FloorLocation, FloorNormal,
        Location - vect(0.00,0.00,512.00), Location, True);

    Log("HPVersusGround phase=" $ Phase
        $ " time=" $ string(Level.TimeSeconds)
        $ " pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " Role=" $ string(Role)
        $ " RemoteRole=" $ string(RemoteRole)
        $ " localViewport=" $ string(bLocalViewport)
        $ " Physics=" $ string(Physics)
        $ " State=" $ string(GetStateName())
        $ " Location=" $ string(Location)
        $ " Velocity=" $ string(Velocity)
        $ " Base=" $ string(Base)
        $ " MountBase=" $ string(MountBase));

    Log("HPVersusGroundShape phase=" $ Phase
        $ " pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " CollisionRadius=" $ string(CollisionRadius)
        $ " CollisionHeight=" $ string(CollisionHeight)
        $ " cylinderBottomZ=" $ string(Location.Z - CollisionHeight)
        $ " bCollideWorld=" $ string(bCollideWorld)
        $ " bCollideActors=" $ string(bCollideActors)
        $ " Mesh=" $ string(Mesh)
        $ " DrawScale=" $ string(DrawScale)
        $ " PrePivot=" $ string(PrePivot)
        $ " SavedPrePivotZ=" $ string(SavedPrePivotZ)
        $ " bAlignBottom=" $ string(bAlignBottom)
        $ " bAlignBottomAlways=" $ string(bAlignBottomAlways)
        $ " AnimSequence=" $ string(AnimSequence)
        $ " AnimFrame=" $ string(AnimFrame)
        $ " AnimRate=" $ string(AnimRate)
        $ " bAnimLoop=" $ string(bAnimLoop)
        $ " bAnimFinished=" $ string(bAnimFinished)
        $ " SimAnimX=" $ string(SimAnim.X)
        $ " SimAnimY=" $ string(SimAnim.Y)
        $ " SimAnimZ=" $ string(SimAnim.Z)
        $ " SimAnimW=" $ string(SimAnim.W));

    if (FloorActor != None)
        Log("HPVersusGroundTrace phase=" $ Phase
            $ " pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " hit=" $ string(FloorActor)
            $ " hitClass=" $ string(FloorActor.Class)
            $ " hitLocation=" $ string(FloorLocation)
            $ " hitNormal=" $ string(FloorNormal)
            $ " cylinderGap=" $ string(Location.Z - CollisionHeight - FloorLocation.Z));
    else
        Log("HPVersusGroundTrace phase=" $ Phase
            $ " pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " hit=None range=512");

    // BonePos is used by HP2 actors; these foot names are used by Harry's
    // own Spongify effects. This is a client pose-cache observation, not an
    // authoritative collider. Dedicated does not have a rendered pose.
    if (Mesh != None && Level.NetMode != NM_DedicatedServer)
    {
        LeftFoot = BonePos('Bip01 L Foot');
        RightFoot = BonePos('Bip01 R Foot');
        Log("HPVersusGroundFeet phase=" $ Phase
            $ " pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " source=BonePosCache"
            $ " left=" $ string(LeftFoot)
            $ " right=" $ string(RightFoot)
            $ " leftRelativeZ=" $ string(LeftFoot.Z - Location.Z)
            $ " rightRelativeZ=" $ string(RightFoot.Z - Location.Z));
    }
}

function VersusDumpGroundState()
{
    local HPVersusHarry H;
    local string Phase;

    if (!IsLocalViewportPlayer())
        return;

    VersusGroundProbeSerial++;
    Phase = "GroundProbe_" $ string(VersusSlot) $ "_" $ string(VersusGroundProbeSerial);
    foreach AllActors(Class'HPVersusHarry', H)
        H.LogVersusGroundState(Phase);

    if (Role < ROLE_Authority)
        ServerVersusNetState(Phase);

    ClientMessage("Versus floor/mesh snapshot: " $ Phase);
}

function VersusDumpNetState()
{
    LogVersusNetState("ClientExec");

    if (Role < ROLE_Authority)
        ServerVersusNetState("ClientExec");

    ClientMessage("Versus state logged: mode=" $ VersusMovementModeName()
        $ " role=" $ string(Role)
        $ " state=" $ string(GetStateName())
        $ " anim=" $ string(AnimSequence));
}

function OnHarryProcessMoveComplete()
{
    // ServerMove calls ProcessMove before AutonomousPhysics. This is a known
    // authority callback, not a post-physics tick. The animation classifier
    // keeps an active movement loop while speed crosses zero on a reversal.
    KeepVersusBodyUpright();

    if (!bUseEngineNetworkMovement)
    {
        ReconcileVersusMovementAnimation("ProcessMoveDirect");
        return;
    }

    ReconcileVersusMovementAnimation("ProcessMove");

    if (Level.TimeSeconds < NextVersusNativeTraceTime)
        return;

    LogVersusNetState("ProcessMovePost");
    NextVersusNativeTraceTime = Level.TimeSeconds + 0.25;
}

function OnHarryReplicatedMoveComplete()
{
    // ReplicateMove has already run ProcessMove and AutonomousPhysics on the
    // owning client. Do not execute physics again or depend on pawn.Tick.
    KeepVersusBodyUpright();
    ReconcileVersusMovementAnimation("ReplicateMovePostPhysics");
}

function OnEngineNetworkCorrectionApplied()
{
    if (!bUseEngineNetworkMovement)
        return;

    KeepVersusBodyUpright();
    ReconcileVersusMovementAnimation("CorrectionReplay");

    if (Level.TimeSeconds < NextVersusCorrectionTraceTime)
        return;

    LogVersusNetState("CorrectionReplayPost");
    NextVersusCorrectionTraceTime = Level.TimeSeconds + 0.25;
}

function ForceVersusViewTarget()
{
    if (!IsLocalViewportPlayer())
        return;

    if (Cam == None)
        return;

    ViewTarget = Cam;
    bBehindView = True;
    Cam.BecomeViewTarget();
}

function CleanupLocalLegacyHarry()
{
    local harry H;

    if (!IsLocalViewportPlayer())
        return;

    foreach AllActors(Class'harry', H)
    {
        if (H == None || H == self)
            continue;

        if (HPVersusHarry(H) != None)
            continue;

        Log("HPVersusHarry: hiding legacy single-player pawn " $ string(H) $ " while local pawn is " $ string(self));
        H.bHidden = True;
        H.SetCollision(False, False, False);
        H.Destroy();
    }
}

function BaseCam EnsureVersusCamera()
{
    local BaseCam C;

    if (!IsLocalViewportPlayer())
        return Cam;

    if (Cam != None)
        return Cam;

    foreach AllActors(Class'BaseCam', C)
        break;

    if (C == None)
        C = Spawn(Class'BaseCam');

    if (C == None)
    {
        Log("HPVersusHarry: failed to find/spawn BaseCam for " $ string(self));
        return None;
    }

    if (C.CamTarget == None)
    {
        C.CamTarget = Spawn(Class'BaseCamTarget');
        if (C.CamTarget != None)
            C.CamTarget.Cam = C;
    }

    Cam = C;
    ForceVersusViewTarget();

    Log("HPVersusHarry: assigned cam=" $ string(C) $ " to " $ string(self)
        $ " viewTarget=" $ string(ViewTarget)
        $ " bBehindView=" $ string(bBehindView));
    return Cam;
}

function Class<baseSpell> GetVersusSpellClass(byte SpellSlot)
{
    // Clients send only a slot. The server maps it through this fixed whitelist.
    switch (SpellSlot)
    {
        case 0:
            return Class'HPVersusSpell';
        case 1:
            return Class'HPVersusMimblewimble';
        case 2:
            return Class'HPVersusExpelliarmus';
        case 3:
            return Class'HPVersusFlipendo';
        case 4:
            return Class'HPVersusAlohomora';
        case 5:
            return Class'HPVersusSpongify';
        default:
            return None;
    }
}

simulated function string GetVersusSpellName(byte SpellSlot)
{
    switch (SpellSlot)
    {
        case 0: return "Rictusempra";
        case 1: return "Mimblewimble";
        case 2: return "Expelliarmus";
        case 3: return "Flipendo";
        case 4: return "Alohomora";
        case 5: return "Spongify";
    }
    return "Unknown";
}

simulated function float GetVersusSpellCooldown(byte SpellSlot)
{
    switch (SpellSlot)
    {
        case 0: return 0.35;
        case 1: return 0.70;
        case 2: return 1.00;
        case 3: return 0.60;
        case 4: return 0.60;
        case 5: return 0.80;
    }
    return VersusCastCooldown;
}

function HPVersusWand FindVersusWand()
{
    local Inventory Item;
    local HPVersusWand W;

    for (Item = Inventory; Item != None; Item = Item.Inventory)
    {
        W = HPVersusWand(Item);
        if (W != None)
            return W;
    }

    return None;
}

function ApplyVersusSpellSelection(HPVersusWand W)
{
    local Class<baseSpell> SpellClass;

    if (W == None)
        return;

    SpellClass = GetVersusSpellClass(SelectedVersusSpell);
    if (SpellClass == None)
    {
        SelectedVersusSpell = 0;
        SpellClass = GetVersusSpellClass(SelectedVersusSpell);
    }

    W.bAutoSelectSpell = False;
    W.SetCurrentSpell(SpellClass, True);
}

function HPVersusWand EnsureServerVersusWand()
{
    local HPVersusWand W;
    local bool bCreated;

    if (Role != ROLE_Authority)
        return HPVersusWand(Weapon);

    W = FindVersusWand();
    if (W == None)
    {
        W = Spawn(Class'HPVersusWand', self);
        if (W != None)
        {
            W.BecomeItem();
            if (!AddInventory(W))
            {
                Log("HPVersusWandAssign ADD_INVENTORY_FAILED pawn="
                    $ string(self) $ " wand=" $ string(W));
                W.Destroy();
                W = None;
            }
            else
            {
                bCreated = True;
                W.WeaponSet(self);
                W.GiveAmmo(self);
            }
        }
    }

    if (W == None)
    {
        Log("HPVersusWandAssign FAILED pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " inventory=" $ string(Inventory)
            $ " weapon=" $ string(Weapon));
        return None;
    }

    W.SetOwner(self);
    W.Instigator = self;
    W.BindVersusOwner();
    ApplyVersusSpellSelection(W);

    // A transferred legacy baseWand can already occupy Weapon.  Keep it in
    // inventory for compatibility, but explicitly select this pawn's own
    // HPVersusWand so casts can never belong to Entry.Harry0.
    if (Weapon != W)
    {
        PendingWeapon = W;
        ChangedWeapon();
    }

    Log("HPVersusWandAssign pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " created=" $ string(bCreated)
        $ " wand=" $ string(W)
        $ " owner=" $ string(W.Owner)
        $ " instigator=" $ string(W.Instigator)
        $ " activeWeapon=" $ string(Weapon)
        $ " selectedSlot=" $ string(SelectedVersusSpell)
        $ " currentSpell=" $ string(W.CurrentSpell));

    return W;
}

function PreventVersusCursorReplication()
{
    if (Role != ROLE_Authority || SpellCursor == None)
        return;

    // The cursor and gesture are reconstructed locally by the owning
    // viewport.  Replicating the server copies can leave an inert particle
    // actor at their initial map location -- the visible "fixed point".
    SpellCursor.RemoteRole = ROLE_None;
    if (SpellCursor.SpellGesture != None)
        SpellCursor.SpellGesture.RemoteRole = ROLE_None;
}

function DisableNonLocalVersusCursor()
{
    if (SpellCursor == None)
        return;

    // harry.PreBeginPlay creates one ownerless cursor for every replicated
    // pawn.  Remote and dedicated copies must never render or use the shared
    // Level.PlayerHarryActor/BaseCam globals.
    PreventVersusCursorReplication();

    SpellCursor.SetOwner(self);
    SpellCursor.PlayerHarry = self;
    SpellCursor.TickParent = None;
    SpellCursor.EnableEmission(False);
    SpellCursor.bHidden = True;
    SpellCursor.Disable('Tick');

    if (SpellCursor.SpellGesture != None)
        SpellCursor.SpellGesture.bHidden = True;
}

function SetupVersusSpellObjects(string Phase)
{
    local HPVersusWand W;
    local bool bReferencesChanged;

    W = HPVersusWand(Weapon);
    if (W == None)
        W = FindVersusWand();

    if (W != None)
    {
        W.BindVersusOwner();
        W.bAutoSelectSpell = False;
        W.ApplyVersusVisualSpell(SelectedVersusSpell);
    }

    PreventVersusCursorReplication();

    if (!IsLocalViewportPlayer()
        || bVersusDead
        || Health <= 0
        || Cam == None)
    {
        DisableNonLocalVersusCursor();
    }
    else
    {
        if (SpellCursor == None)
        {
            SpellCursor = Spawn(Class'SpellCursor', self);
            PreventVersusCursorReplication();
        }

        if (SpellCursor != None)
        {
            bReferencesChanged = SpellCursor.Owner != self
                || SpellCursor.PlayerHarry != self
                || SpellCursor.TickParent != Cam;

            SpellCursor.SetOwner(self);
            SpellCursor.PlayerHarry = self;
            SpellCursor.TickParent = Cam;
            SpellCursor.Enable('Tick');
            SpellCursor.bHidden = False;

            if (bReferencesChanged)
            {
                SpellCursor.SetLocation(Location);
                SpellCursor.TurnTargetingOff();
            }
        }
    }

    if (Phase != "PlayerInput"
        || Weapon != LastLoggedVersusWeapon
        || SpellCursor != LastLoggedVersusCursor)
    {
        LogVersusSpellState(Phase);
        LastLoggedVersusWeapon = Weapon;
        LastLoggedVersusCursor = SpellCursor;
    }
}

