function float VersusAxisSign(float V)
{
    if (V > 0.0)
        return 1.0;

    if (V < 0.0)
        return -1.0;

    return 0.0;
}

function rotator GetVersusMoveRotation()
{
    local rotator R;

    if (IsVersusFreeLookDetached())
        R = VersusFreeLookPawnRotation;
    else if (IsLocalViewportPlayer() && Cam != None)
        R = Cam.Rotation;
    else
        R = ViewRotation;

    R.Pitch = 0;
    R.Roll = 0;
    return R;
}

function bool VersusDirectMove(float ForwardAxis, float StrafeAxis, float DeltaTime, rotator MoveRot, bool bServerSide)
{
    local vector X;
    local vector Y;
    local vector Z;
    local vector Dir;
    local vector Step;
    local float Speed;
    local bool bMoved;

    ForwardAxis = VersusAxisSign(ForwardAxis);
    StrafeAxis = VersusAxisSign(StrafeAxis);

    if (ForwardAxis == 0.0 && StrafeAxis == 0.0)
        return False;

    if (DeltaTime <= 0.0)
        DeltaTime = 0.05;

    if (DeltaTime > 0.12)
        DeltaTime = 0.12;

    if (VersusDirectMoveSpeed <= 0.0)
        VersusDirectMoveSpeed = 260.0;

    if (VersusDirectAirScale <= 0.0)
        VersusDirectAirScale = 0.45;

    bKeepStationary = False;
    bIsCaptured = False;
    bFrozen = False;
    bCanMoveInSpecialPause = True;

    MoveRot.Pitch = 0;
    MoveRot.Roll = 0;
    GetAxes(MoveRot, X, Y, Z);

    Dir = ForwardAxis * X + StrafeAxis * Y;
    Dir.Z = 0.0;

    if (VSize(Dir) > 1.0)
        Dir = Normal(Dir);

    Speed = VersusDirectMoveSpeed;
    if (Physics == PHYS_Falling)
        Speed *= VersusDirectAirScale;

    Step = Dir * Speed * DeltaTime;
    bMoved = MoveSmooth(Step);

    // Keep animation and diagnostics alive even though movement is explicit.
    Acceleration = Dir * 504.0;
    if (DeltaTime > 0.0)
    {
        Velocity.X = Step.X / DeltaTime;
        Velocity.Y = Step.Y / DeltaTime;
    }

    if (Level.TimeSeconds >= NextVersusMoveLogTime)
    {
        Log("HPVersusDirectMove pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " server=" $ string(bServerSide)
            $ " F=" $ string(ForwardAxis)
            $ " S=" $ string(StrafeAxis)
            $ " moved=" $ string(bMoved)
            $ " step=" $ string(Step)
            $ " loc=" $ string(Location)
            $ " vel=" $ string(Velocity)
            $ " acc=" $ string(Acceleration)
            $ " physics=" $ string(Physics));
        NextVersusMoveLogTime = Level.TimeSeconds + 0.25;
    }

    return bMoved;
}

function ServerVersusMoveInput(float ForwardAxis, float StrafeAxis, byte bJumpNow, float DeltaTime, int MoveYaw)
{
    local rotator MoveRot;

    if (Role != ROLE_Authority)
        return;

    // Reliable mode switching is ordered with the v7 reliable movement RPC,
    // so queued direct moves cannot continue after the native probe is enabled.
    if (bUseEngineNetworkMovement)
        return;

    bKeepStationary = False;
    bIsCaptured = False;
    bFrozen = False;
    bCanMoveInSpecialPause = True;

    if (!IsInState('PlayerWalking'))
        GotoState('PlayerWalking');

    if (Physics == PHYS_None || Physics == PHYS_Rotating)
        SetPhysics(PHYS_Walking);

    if (bJumpNow != 0 && Physics != PHYS_Falling)
        DoJump();

    MoveRot.Yaw = MoveYaw;
    MoveRot.Pitch = 0;
    MoveRot.Roll = 0;

    VersusDirectMove(ForwardAxis, StrafeAxis, DeltaTime, MoveRot, True);
}

function ApplyVersusInput(float DeltaTime)
{
    local float ForcedForward;
    local float ForcedStrafe;
    local rotator MoveRot;
    local byte bJumpEdge;

    if (bVersusDead || !IsLocalViewportPlayer())
        return;

    // Keep the pawn in a controllable state.  HP2 single-player cutscene/menu
    // paths can leave these flags latched after network travel.
    bKeepStationary = False;
    bIsCaptured = False;
    bFrozen = False;
    bCanMoveInSpecialPause = True;

    if (!IsInState('PlayerWalking'))
        GotoState('PlayerWalking');

    if (Physics == PHYS_None || Physics == PHYS_Rotating)
        SetPhysics(PHYS_Walking);

    if (bVersusMoveForward != 0)
        ForcedForward += 300.0;

    if (bVersusMoveBack != 0)
        ForcedForward -= 300.0;

    if (bVersusMoveLeft != 0)
        ForcedStrafe -= 300.0;

    if (bVersusMoveRight != 0)
        ForcedStrafe += 300.0;

    if (ForcedForward != 0.0 || ForcedStrafe != 0.0)
    {
        // Super.PlayerInput has already transformed normal input.  Add our
        // fallback axes after it, so PlayerWalking.PlayerMove will consume them
        // and ReplicateMove will send the resulting acceleration to the server.
        aForward += ForcedForward;
        aStrafe += ForcedStrafe;
    }

    // Button variables stay non-zero while held.  bPressedJump is an edge,
    // otherwise Harry immediately jumps again on the first walking frame and
    // appears permanently stuck in the jump sequence.
    if (bVersusJump != 0 && bVersusJumpWasDown == 0)
    {
        bPressedJump = True;
        bJumpEdge = 1;
    }
    bVersusJumpWasDown = bVersusJump;

    if (!bUseEngineNetworkMovement && (ForcedForward != 0.0 || ForcedStrafe != 0.0 || bJumpEdge != 0))
    {
        // Explicit movement bridge.  The local call gives immediate feedback;
        // the RPC moves the authoritative server pawn and replicates it to the
        // other client.  This is intentionally separate from HP2's original
        // harry.PlayerMove path, because that path never calls ReplicateMove.
        MoveRot = GetVersusMoveRotation();
        VersusDirectMove(ForcedForward, ForcedStrafe, DeltaTime, MoveRot, False);

        if (Role < ROLE_Authority)
            ServerVersusMoveInput(ForcedForward, ForcedStrafe, bJumpEdge, DeltaTime, MoveRot.Yaw);
    }

    if ((ForcedForward != 0.0 || ForcedStrafe != 0.0 || bJumpEdge != 0) && Level.TimeSeconds >= NextVersusInputLogTime)
    {
        Log("HPVersusInput pawn=" $ string(self)
            $ " slot=" $ string(VersusSlot)
            $ " F=" $ string(bVersusMoveForward)
            $ " B=" $ string(bVersusMoveBack)
            $ " L=" $ string(bVersusMoveLeft)
            $ " R=" $ string(bVersusMoveRight)
            $ " J=" $ string(bVersusJump)
            $ " aForward=" $ string(aForward)
            $ " aStrafe=" $ string(aStrafe)
            $ " state=" $ string(GetStateName())
            $ " physics=" $ string(Physics)
            $ " loc=" $ string(Location)
            $ " vel=" $ string(Velocity)
            $ " acc=" $ string(Acceleration));
        NextVersusInputLogTime = Level.TimeSeconds + 0.25;
    }
}

