exec function VersusNudgeForward(optional float Dist)
{
    local vector X;
    local vector Y;
    local vector Z;
    local vector D;

    if (Dist == 0.0)
        Dist = 80.0;

    GetAxes(Rotation, X, Y, Z);
    D = X * Dist;

    // Client-side immediate feedback, then server authority.
    SetLocation(Location + D);

    if (Role < ROLE_Authority)
        ServerVersusNudge(D.X, D.Y, D.Z);
}

function ServerVersusNudge(float DX, float DY, float DZ)
{
    local vector D;

    if (Role != ROLE_Authority)
        return;

    D.X = DX;
    D.Y = DY;
    D.Z = DZ;
    SetLocation(Location + D);

    Log("ServerVersusNudge pawn=" $ string(self)
        $ " slot=" $ string(VersusSlot)
        $ " d=" $ string(D)
        $ " loc=" $ string(Location));
}

event PlayerInput(float DeltaTime)
{
    local HPVersusHarry ObservedHarry;

    if (IsLocalViewportPlayer() && !bVersusMovementChoiceMade)
    {
        Log("HPVersusMovementAuto pawn=" $ string(self) $ " mode=Native");
        SetVersusEngineMovement(True);
    }

    if (bVersusDead)
    {
        ClearVersusInput();
        return;
    }

    if (IsLocalViewportPlayer())
    {
        Level.PlayerHarryActor = self;
        bKeepStationary = False;
        bIsCaptured = False;
        // The camera is already bound before Alt begins. Do not call even
        // InitTarget/Stabilize paths each held frame; keep only the viewport.
        if (bVersusFreeLook == 0 && !bVersusFreeLookActive)
            class'HPVersusCamera'.static.ApplyStandardCam(self);
        ForceVersusViewTarget();
        SetupVersusSpellObjects("PlayerInput");
    }

    Super.PlayerInput(DeltaTime);
    UpdateVersusFreeLook();
    if (bVersusModeMovementLocked)
    {
        ClearVersusInput();
        aForward = 0.0;
        aStrafe = 0.0;
        bPressedJump = False;
        Velocity = vect(0,0,0);
        Acceleration = vect(0,0,0);
        if (IsVersusJumpOrFallAnim(AnimSequence)
            || IsVersusMovementAnim(AnimSequence)
            || AnimRate <= 0.0)
            ResetHideSeekLockedAnimation();
        return;
    }
    ApplyVersusInput(DeltaTime);

    // Network PlayerPawn tick dispatch differs from ordinary actors. Drive
    // visual-only proxies from this viewport's proven input callback, even
    // while its keys are released. Never run their owner/bootstrap methods.
    if (IsLocalViewportPlayer())
    {
        foreach AllActors(Class'HPVersusHarry', ObservedHarry)
            if (ObservedHarry != self && ObservedHarry.Role == ROLE_SimulatedProxy)
                ObservedHarry.UpdateVersusProxyPresentation();
    }
}

function Timer()
{
    // Do not call harry.Timer(): it restores Health to 100 every second AND
    // re-forces the camera, both of which make a duel impossible and fight the
    // host camera. Keep only the animation timer.
    SleepyAnimTimerSub();
}

function SetHealth(int iHealth)
{
    Health = iHealth;
}

function AddHealth(int iHealth)
{
    Health += iHealth;

    if (Health < 0)
        Health = 0;
}

function int GetHealthCount()
{
    return Health;
}

function int VersusDamage(int MinDamage, int Damage)
{
    if (Damage < MinDamage)
        return MinDamage;

    return Damage;
}

function KillHarry(bool bImmediateDeath)
{
    if (Role != ROLE_Authority)
        return;

    VersusKilledBy(None, 'Killed');
}

function KillHarryWithClub(bool bImmediateDeath, Actor A)
{
    if (Role != ROLE_Authority)
        return;

    VersusKilledBy(Pawn(A), 'Club');
}

function Died(Pawn Killer, name DamageType, Vector HitLocation)
{
    if (Role != ROLE_Authority)
        return;

    VersusKilledBy(Killer, DamageType);
}

function TakeDamage(int Damage, Pawn InstigatedBy, vector HitLocation, vector Momentum, name DamageType)
{
    local int OldHealth;
    local HPVersusGame VG;

    if (Role != ROLE_Authority)
        return;
    VG = HPVersusGame(Level.Game);
    if (VG != None
        && !VG.IsVersusDamageAllowed(self, InstigatedBy, DamageType))
        return;
    if (HPVersusGame(Level.Game) != None && !HPVersusGame(Level.Game).bMatchInProgress)
        return;

    if (bVersusDead)
        return;

    if (Damage <= 0)
        return;

    OldHealth = Health;
    AddHealth(-Damage);
    if (Health > 100)
        Health = 100;
    LastVersusHitTime = Level.TimeSeconds;
    ClientSyncHealth(Health);

    Log("HPVersusDamage victim=" $ string(self)
        $ " victimSlot=" $ string(VersusSlot)
        $ " instigator=" $ string(InstigatedBy)
        $ " damage=" $ string(Damage)
        $ " oldHealth=" $ string(OldHealth)
        $ " newHealth=" $ string(Health)
        $ " type=" $ string(DamageType)
        $ " hit=" $ string(HitLocation));

    if (Health <= 0 || GetHealthCount() <= 0)
    {
        VersusKilledBy(InstigatedBy, DamageType);
        return;
    }

    PlayHurtEmoteSound();
    HarryKnockBack();
}

function bool HandleSpellDuelRictusempra(optional baseSpell spell, optional Vector vHitLocation)
{
    local int Damage;
    local HPVersusGame VG;
    local Pawn Attacker;

    if (Role != ROLE_Authority)
        return False;

    if (spell != None)
        Attacker = Pawn(spell.Owner);
    VG = HPVersusGame(Level.Game);
    if (VG != None && VG.HandleVersusRictusempraModeHit(self, Attacker))
        return True;

    if (spell == None)
        TakeDamage(15, None, Location, vect(0.00,0.00,0.00), 'DuelRictusempra');
    else {
        Damage = VersusDamage(5, int(15 * spell.SpellCharge));
        TakeDamage(Damage, Pawn(spell.Owner), vHitLocation, vect(0.00,0.00,0.00), 'DuelRictusempra');
    }

    return True;
}

function bool HandleSpellDuelMimblewimble(optional baseSpell spell, optional Vector vHitLocation)
{
    local int Damage;
    local float Charge;
    local Pawn Attacker;

    if (Role != ROLE_Authority)
        return False;

    Charge = 1.0;
    if (spell != None)
    {
        Charge = FClamp(spell.SpellCharge, 0.0, 1.0);
        Attacker = Pawn(spell.Owner);
    }
    Damage = VersusDamage(3, int(8 * Charge));
    TakeDamage(Damage, Attacker, vHitLocation,
        vect(0.00,0.00,0.00), 'DuelMimblewimble');
    if (!bVersusDead)
        ApplyVersusSpellLock(0.75 + 0.75 * Charge);

    return True;
}

function bool HandleSpellDuelExpelliarmus(optional baseSpell spell, optional Vector vHitLocation)
{
    local float Charge;

    if (Role != ROLE_Authority || bVersusDead)
        return False;

    Charge = 1.0;
    if (spell != None)
        Charge = FClamp(spell.SpellCharge, 0.0, 1.0);

    // Stock duelists cast Expelliarmus as a timed defence when an incoming
    // spell is close. In FFA the corresponding minimal network mechanic is a
    // non-damaging cast interruption plus a short authoritative disarm window.
    ApplyVersusDisarm(0.45 + 0.45 * Charge);
    return True;
}

function VersusKilledBy(Pawn Killer, name DamageType)
{
    local HPVersusGame VG;

    if (bVersusDead)
        return;

    bVersusDead = True;
    Health = 0;
    SetHealth(0);
    ResetVersusCombatEffects();
    ClearVersusInput();
    GotoState('VersusDead');
    ClientVersusDeath();

    VG = HPVersusGame(Level.Game);
    if (VG != None)
        VG.NotifyVersusDeath(self, Killer, DamageType);
}

function ClientVersusDeath()
{
    ResetVersusFreeLook("Death");
    bVersusDead = True;
    Health = 0;
    ResetVersusCombatEffects();
    ClearVersusInput();
    GotoState('VersusDead');
}

function ClientVersusRespawn(optional bool bPreserveLiveCamera)
{
    bVersusDead = False;
    bPreserveVersusCameraOnSetup = bPreserveLiveCamera
        && IsLocalViewportPlayer() && Cam != None;
    SetupVersusPlayer();
