function ApplyCharacterSkin(string CharacterName)
{
    local Texture ProfileSkin;

    CharacterName = class'HPVersusCharacterProfiles'.static.ValidateProfileId(
        CharacterName);

    // Presentation changes never modify the accepted gameplay cylinder.
    SetCollisionSize(Default.CollisionRadius, Default.CollisionHeight);
    Mesh = class'HPVersusCharacterProfiles'.static.GetMesh(CharacterName);
    DrawScale = class'HPVersusCharacterProfiles'.static.GetDrawScale(
        CharacterName);
    PrePivot = Default.PrePivot;
    PrePivot.Z += class'HPVersusCharacterProfiles'.static.GetVisualOffsetZ(
        CharacterName);
    bAlignBottom = True;
    bAlignBottomAlways = True;

    MultiSkins[0] = Default.MultiSkins[0];
    MultiSkins[1] = Default.MultiSkins[1];
    ProfileSkin = class'HPVersusCharacterProfiles'.static.GetSkin(
        CharacterName, 0);
    if (ProfileSkin != None)
        MultiSkins[0] = ProfileSkin;
    ProfileSkin = class'HPVersusCharacterProfiles'.static.GetSkin(
        CharacterName, 1);
    if (ProfileSkin != None)
        MultiSkins[1] = ProfileSkin;

    if (class'HPVersusCharacterProfiles'.static.IsTranslucent(CharacterName))
        Style = STY_Translucent;
    else
        Style = STY_Normal;
    Opacity = class'HPVersusCharacterProfiles'.static.GetOpacity(CharacterName);

    EnsureVersusPlayerAnimationSet();
    if (UsesStableVersusIdle() && Physics != PHYS_Falling
        && VSize2D(Velocity) < 5.0)
    {
        CurrIdleAnimName = HarryAnims[HarryAnimSet].Idle;
        LoopAnim(CurrIdleAnimName, 0.8, 0.15,, HarryAnimType);
    }
    if (class'HPVersusCharacterProfiles'.static.GetCloakStrategy(Mesh) != 0)
    {
        EnsureVersusCloakAnimationChannels();
        UpdateVersusCloakAnimation();
    }

    Log("HPVersusCharacterSkin pawn=" $ string(self)
        $ " character=" $ CharacterName
        $ " status="
        $ class'HPVersusCharacterProfiles'.static.GetAuditStatus(CharacterName)
        $ " mesh=" $ string(Mesh)
        $ " animSet=" $ string(SkelAnim)
        $ " collision=" $ string(CollisionRadius)
        $ "x" $ string(CollisionHeight)
        $ " wandBone="
        $ string(class'HPVersusCharacterProfiles'.static.GetWandBone(CharacterName))
        $ " wandBoneIndex="
        $ string(BoneNumber(
            class'HPVersusCharacterProfiles'.static.GetWandBone(CharacterName)))
        $ " hasIdle=" $ string(HasAnim(HarryAnims[0].Idle))
        $ " hasRun=" $ string(HasAnim(HarryAnims[0].run))
        $ " hasRunback=" $ string(HasAnim(HarryAnims[0].WalkBack))
        $ " hasStrafeL=" $ string(HasAnim(HarryAnims[0].StrafeLeft))
        $ " hasStrafeR=" $ string(HasAnim(HarryAnims[0].StrafeRight))
        $ " hasJump=" $ string(HasAnim(HarryAnims[0].Jump))
        $ " hasFall=" $ string(HasAnim(HarryAnims[0].Fall))
        $ " hasLand=" $ string(HasAnim(HarryAnims[0].Land))
        $ " hasCast=" $ string(HasAnim('Cast'))
        $ " hasCastAim=" $ string(HasAnim('CastAim'))
        $ " hasFaint=" $ string(HasAnim('faint')));
}

